29	    uint32_t bIdx;
30	    uint32_t n2Idx;
31	    uint32_t gS1Idx;
32	    uint32_t actualCombineLoopSize;
33	};
34	
35	template <typename FIAT> class FiaBlockVecFlashDecode {
36	  public:
37	    // =================================类型定义区=================================
38	    // 中间计算数据类型为float，高精度模式
39	    using T = float;
40	    using OUT_T = typename FIAT::outputType;
41	    static constexpr FIA_LAYOUT LAYOUT_T = FIAT::layout;
42	
43	    __aicore__ inline void InitGlobalTensor(GlobalTensor<T> lseMaxFdGm,
44	                                            GlobalTensor<T> lseSumFdGm,
45	                                            GlobalTensor<T> accumOutGm,
46	                                            GlobalTensor<OUT_T> attentionOutGm,
47	                                            GlobalTensor<uint64_t> actualSeqLengthsGmQ,
48	                                            GlobalTensor<uint64_t> actualSeqLengthsGm);
49	    __aicore__ inline void InitSoftmaxLseGm(GlobalTensor<float> softmaxLseGm);
50	    __aicore__ inline void InitParams(const AttentionCommon::ConstInfo &constInfo);
51	    __aicore__ inline void InitDecodeParams();
52	    __aicore__ inline void InitBuffers(TPipe *pipe);
53	    __aicore__ inline void AllocEventID();
54	    __aicore__ inline void FreeEventID();
55	    __aicore__ inline void FlashDecode(FDparams &fd);
56	
57	  protected:
58	    __aicore__ inline void
59	    CopyAccumOutIn(LocalTensor<T> &accumOutLocal, uint32_t splitKVIndex, uint32_t startRow, uint32_t dealRowCount);
60	    __aicore__ inline void CopyLseIn(uint32_t startRow, uint32_t dealRowCount, uint64_t baseOffset, uint32_t cntM);
61	    __aicore__ inline void
62	    ComputeScaleValue(LocalTensor<T> &lseExp, uint32_t startRow, uint32_t dealRowCount, uint32_t cntM);
63	    __aicore__ inline void Bmm2DataCopyOutTrans(LocalTensor<OUT_T> &attenOutUb,
64	                                                uint32_t startRow,
65	                                                uint32_t dealRowCount,
66	                                                uint32_t columnCount);
67	    __aicore__ inline void Bmm2DataCopyOut(uint64_t attenOutOffset,
68	                                           LocalTensor<OUT_T> &attenOutUb,
69	                                           uint32_t startRow,
70	                                           uint32_t dealRowCount,
71	                                           uint32_t columnCount,
72	                                           uint32_t actualColumnCount);
73	    __aicore__ inline void ReduceFinalRes(LocalTensor<T> &reduceOut,
74	                                          LocalTensor<T> &mm2Res,
75	                                          LocalTensor<T> &lseLocal,
76	                                          uint32_t cntKV,
77	                                          uint32_t dealRowCount);
78	    __aicore__ inline void CopyFinalResOut(LocalTensor<T> &accumOutLocal, uint32_t startRow, uint32_t dealRowCount);
79	    __aicore__ inline void CalaPreNextTokens();
80	
81	  private:
82	    // =================================常量区=================================
83	    static constexpr uint64_t SYNC_LSE_SUM_BUF1_FLAG = 6;
84	    static constexpr uint64_t SYNC_LSE_SUM_BUF2_FLAG = 7;
85	    static constexpr uint64_t SYNC_LSE_MAX_BUF1_FLAG = 8;
86	    static constexpr uint64_t SYNC_LSE_MAX_BUF2_FLAG = 9;
87	    static constexpr uint64_t SYNC_MM2RES_BUF1_FLAG = 10;
88	    static constexpr uint64_t SYNC_MM2RES_BUF2_FLAG = 11;
89	    static constexpr uint64_t SYNC_FDOUTPUT_BUF_FLAG = 6;
90	    static constexpr uint64_t SYNC_LSEOUTPUT_BUF_FLAG = 7;
91	
92	    static constexpr uint32_t BLOCK_ELEMENT_NUM = fa_base_vector::BYTE_BLOCK / sizeof(T); // 32/4=8
93	
94	  protected:
95	    GlobalTensor<T> lseSumFdGm;
96	    GlobalTensor<T> lseMaxFdGm;
97	    GlobalTensor<T> accumOutGm;
98	    GlobalTensor<OUT_T> attentionOutGm;
99	    GlobalTensor<float> softmaxLseGm;
100	    GlobalTensor<uint64_t> actualSeqLengthsGmQ;
101	    GlobalTensor<uint64_t> actualSeqLengthsGm;
102	    // =======================获取实际Act_S，用于行无效处理===========================
103	    static constexpr bool PAGE_ATTENTION = FIAT::pageAttention;
104	    static constexpr ActualSeqLensMode Q_MODE = GetQActSeqMode<LAYOUT_T>();
105	    static constexpr ActualSeqLensMode KV_MODE = GetKvActSeqMode<LAYOUT_T, PAGE_ATTENTION>();
106	    ActualSeqLensParser<Q_MODE> qActSeqLensParser;
107	    ActualSeqLensParser<KV_MODE> kvActSeqLensParser;
108	    uint64_t actSeqLensKv = 0;
109	    uint64_t actSeqLensQ = 0;
110	
111	    int64_t preTokensPerBatch = 0;
112	    int64_t nextTokensPerBatch = 0;
113	
114	    static constexpr T BOOL_ATTEN_MASK_SCALAR_VALUE = -1000000000000.0; // 用于mask为bool类型
115	    uint32_t negativeIntScalar = *((uint32_t *)&BOOL_ATTEN_MASK_SCALAR_VALUE);
116	
117	    // ================================类成员变量====================================
118	    // aic、aiv核信息
119	    uint32_t blockIdx = 0U;
120	    AttentionCommon::ConstInfo constInfo{};
121	    TaskInfo taskInfo{};
122	
123	  private:
124	    // ================================FD Local Buffer区====================================
125	    TBuf<> fdSumBuf1; // 1.5k: 16*24*4
126	    TBuf<> fdSumBuf2; // 1.5k: 16*24*4
127	    TBuf<> fdMaxBuf1; // 1.5k: 16*24*4
128	    TBuf<> fdMaxBuf2; // 1.5k: 16*24*4
129	    TBuf<> fdLseExpBuf; // 1.5k: 16*24*4
130	    TBuf<> fdMm2ResBuf1; // 32k: 16*512*4
131	    TBuf<> fdMm2ResBuf2; // 32k: 16*512*4
132	    TBuf<> fdReduceBuf; // 32k: 16*512*4
133	    TBuf<> fdOutputBuf; // 32k: 16*512*4
134	
135	    TBuf<> fdLseMaxUbBuf; // 64B: 16*4
136	    TBuf<> fdLseSumUbBuf; // 64B: 16*4
137	    TBuf<> fdLseUbBuf; // 64B: 16*4
138	};
