140	template <typename FIAT>
141	__aicore__ inline void FiaBlockVecFlashDecode<FIAT>::InitGlobalTensor(GlobalTensor<T> lseMaxFdGm,
142	                                                                      GlobalTensor<T> lseSumFdGm,
143	                                                                      GlobalTensor<T> accumOutGm,
144	                                                                      GlobalTensor<OUT_T> attentionOutGm,
145	                                                                      GlobalTensor<uint64_t> actualSeqLengthsGmQ,
146	                                                                      GlobalTensor<uint64_t> actualSeqLengthsGm)
147	{
148	    this->lseMaxFdGm = lseMaxFdGm;
149	    this->lseSumFdGm = lseSumFdGm;
150	    this->accumOutGm = accumOutGm;
151	    this->attentionOutGm = attentionOutGm;
152	    this->actualSeqLengthsGmQ = actualSeqLengthsGmQ;
153	    this->actualSeqLengthsGm = actualSeqLengthsGm;
154	
155	    qActSeqLensParser.Init(this->actualSeqLengthsGmQ, constInfo.actualLenQDims, constInfo.qSeqSize);
156	    kvActSeqLensParser.Init(this->actualSeqLengthsGm, constInfo.actualLenDims, constInfo.kvSeqSize);
157	}
158	
159	template <typename FIAT>
160	__aicore__ inline void FiaBlockVecFlashDecode<FIAT>::InitSoftmaxLseGm(GlobalTensor<float> softmaxLseGm)
161	{
162	    this->softmaxLseGm = softmaxLseGm;
163	}
