171	template <typename FIAT> __aicore__ inline void FiaBlockVecFlashDecode<FIAT>::InitDecodeParams()
172	{
173	    this->blockIdx = GetBlockIdx();
174	}
175	
176	template <typename FIAT> __aicore__ inline void FiaBlockVecFlashDecode<FIAT>::InitBuffers(TPipe *pipe)
177	{
178	    if ASCEND_IS_AIV {
179	        pipe->Reset();
180	        pipe->InitBuffer(fdSumBuf1,
181	                         AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_4K +
182	                             AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_2K);
183	        pipe->InitBuffer(fdSumBuf2,
184	                         AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_4K +
185	                             AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_2K);
186	        pipe->InitBuffer(fdMaxBuf1,
187	                         AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_4K +
188	                             AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_2K);
189	        pipe->InitBuffer(fdMaxBuf2,
190	                         AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_4K +
191	                             AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_2K);
192	        pipe->InitBuffer(fdLseExpBuf,
193	                         AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_4K +
194	                             AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_2K);
195	        pipe->InitBuffer(fdMm2ResBuf1, AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_16K);
196	        pipe->InitBuffer(fdMm2ResBuf2, AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_16K);
197	        pipe->InitBuffer(fdReduceBuf, AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_16K);
198	        pipe->InitBuffer(fdOutputBuf, AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_16K);
199	        pipe->InitBuffer(fdLseMaxUbBuf, AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_256B);
200	        pipe->InitBuffer(fdLseSumUbBuf, AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_256B);
201	        pipe->InitBuffer(fdLseUbBuf, AttentionCommon::ConstInfo::BUFFER_SIZE_BYTE_256B);
202	    }
203	}
204	
205	template <typename FIAT> __aicore__ inline void FiaBlockVecFlashDecode<FIAT>::AllocEventID()
206	{
207	    SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_SUM_BUF1_FLAG);
208	    SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_SUM_BUF2_FLAG);
209	    SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_MAX_BUF1_FLAG);
210	    SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_MAX_BUF2_FLAG);
211	    SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_MM2RES_BUF1_FLAG);
212	    SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_MM2RES_BUF2_FLAG);
213	    SetFlag<AscendC::HardEvent::MTE3_V>(SYNC_FDOUTPUT_BUF_FLAG);
214	    SetFlag<AscendC::HardEvent::MTE3_V>(SYNC_LSEOUTPUT_BUF_FLAG);
215	}
216	
217	template <typename FIAT> __aicore__ inline void FiaBlockVecFlashDecode<FIAT>::FreeEventID()
218	{
219	    WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_SUM_BUF1_FLAG);
220	    WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_SUM_BUF2_FLAG);
221	    WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_MAX_BUF1_FLAG);
222	    WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_MAX_BUF2_FLAG);
223	    WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_MM2RES_BUF1_FLAG);
224	    WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_MM2RES_BUF2_FLAG);
225	    WaitFlag<AscendC::HardEvent::MTE3_V>(SYNC_FDOUTPUT_BUF_FLAG);
226	    WaitFlag<AscendC::HardEvent::MTE3_V>(SYNC_LSEOUTPUT_BUF_FLAG);
227	}
228	
229	template <typename FIAT>
230	__aicore__ inline void FiaBlockVecFlashDecode<FIAT>::CopyAccumOutIn(LocalTensor<T> &accumOutLocal,
231	                                                                    uint32_t splitKVIndex,
232	                                                                    uint32_t startRow,
233	                                                                    uint32_t dealRowCount)
234	{
235	    DataCopyExtParams copyInParams;
236	    DataCopyPadExtParams<T> copyInPadParams;
237	    copyInParams.blockCount = dealRowCount;
238	    copyInParams.blockLen = constInfo.headDim * sizeof(T);
239	    copyInParams.srcStride = 0;
240	    copyInParams.dstStride = (constInfo.headDimAlign - constInfo.headDim) / BLOCK_ELEMENT_NUM;
241	
242	    copyInPadParams.isPad = true;
243	    copyInPadParams.leftPadding = 0;
244	    copyInPadParams.rightPadding = (constInfo.headDimAlign - constInfo.headDim) % BLOCK_ELEMENT_NUM;
245	    copyInPadParams.paddingValue = 0;
246	    uint64_t combineAccumOutOffset = startRow * constInfo.headDim + // taskoffset + g轴offset
247	                                     splitKVIndex * constInfo.mBaseSize * constInfo.headDim; // 份数offset
248	
249	    DataCopyPad(accumOutLocal, accumOutGm[combineAccumOutOffset], copyInParams, copyInPadParams);
250	}
