279	template <typename FIAT>
280	__aicore__ inline void FiaBlockVecFlashDecode<FIAT>::ComputeScaleValue(LocalTensor<T> &lseExp,
281	                                                                       uint32_t startRow,
282	                                                                       uint32_t dealRowCount,
283	                                                                       uint32_t cntM)
284	{
285	    LocalTensor<T> lseSum = cntM % 2 == 0 ? fdSumBuf1.Get<T>() : fdSumBuf2.Get<T>();
286	    LocalTensor<T> lseMax = cntM % 2 == 0 ? fdMaxBuf1.Get<T>() : fdMaxBuf2.Get<T>();
287	
288	    LocalTensor<T> lseMaxUb = fdLseMaxUbBuf.Get<T>();
289	    LocalTensor<T> lseSumUb = fdLseSumUbBuf.Get<T>();
290	    uint64_t dealRowCountAlign = dealRowCount * fa_base_vector::FP32_BLOCK_ELEMENT_NUM;
291	    Duplicate(lseMaxUb, -AttentionCommon::ConstInfo::FLOAT_MAX, dealRowCountAlign);
292	    Duplicate(lseSumUb, AttentionCommon::ConstInfo::FLOAT_ZERO, dealRowCountAlign);
293	    AscendC::PipeBarrier<PIPE_V>();
294	
295	    fa_base_vector::ColMax(
296	        lseMaxUb, lseMax, lseMaxUb, taskInfo.actualCombineLoopSize, dealRowCountAlign, dealRowCountAlign);
297	    AscendC::PipeBarrier<PIPE_V>();
298	
299	    fa_base_vector::RowSub(
300	        lseExp, lseMax, lseMaxUb, taskInfo.actualCombineLoopSize, dealRowCountAlign, dealRowCountAlign);
301	    AscendC::PipeBarrier<PIPE_V>();
302	
303	    Exp(lseExp, lseExp, taskInfo.actualCombineLoopSize * dealRowCountAlign);
304	    AscendC::PipeBarrier<PIPE_V>();
305	
306	    Mul(lseExp, lseSum, lseExp, taskInfo.actualCombineLoopSize * dealRowCountAlign);
307	    AscendC::PipeBarrier<PIPE_V>();
308	
309	    fa_base_vector::ColAdd(
310	        lseSumUb, lseExp, lseSumUb, taskInfo.actualCombineLoopSize, dealRowCountAlign, dealRowCountAlign);
311	    AscendC::PipeBarrier<PIPE_V>();
312	
313	    fa_base_vector::MatDivsVec(
314	        lseExp, lseExp, lseSumUb, taskInfo.actualCombineLoopSize, dealRowCountAlign, dealRowCountAlign);
315	    AscendC::PipeBarrier<PIPE_V>();
316	}
