414	template <typename FIAT>
415	__aicore__ inline void FiaBlockVecFlashDecode<FIAT>::ReduceFinalRes(
416	    LocalTensor<T> &reduceOut, LocalTensor<T> &mm2Res, LocalTensor<T> &lseLocal, uint32_t cntKV, uint32_t dealRowCount)
417	{
418	    uint32_t dealRowCountAlign = dealRowCount * fa_base_vector::FP32_BLOCK_ELEMENT_NUM;
419	    LocalTensor<T> tmpRst =
420	        cntKV == 0 ? reduceOut : mm2Res; // 第一次mul结果直接写入reduceOut，否则在mm2Res原地进行mul，再加到reduceOut
421	
422	    fa_base_vector::RowMuls(
423	        tmpRst, mm2Res, lseLocal[cntKV * dealRowCountAlign], dealRowCount, constInfo.headDimAlign, constInfo.headDim);
424	
425	    if (cntKV != 0) {
426	        AscendC::PipeBarrier<PIPE_V>();
427	        Add(reduceOut, reduceOut, tmpRst, dealRowCount * constInfo.headDimAlign);
428	        AscendC::PipeBarrier<PIPE_V>();
429	    }
