453	template <typename FIAT> __aicore__ inline void FiaBlockVecFlashDecode<FIAT>::CalaPreNextTokens()
454	{
455	    actSeqLensQ = qActSeqLensParser.GetActualSeqLength(taskInfo.bIdx);
456	    actSeqLensKv = kvActSeqLensParser.GetActualSeqLength(taskInfo.bIdx);
457	
458	    if (constInfo.sparseMode == fa_base_vector::BAND) {
459	        preTokensPerBatch = constInfo.preToken;
460	        nextTokensPerBatch =
461	            static_cast<int32_t>(actSeqLensKv) - static_cast<int32_t>(actSeqLensQ) + constInfo.nextToken;
462	        if (constInfo.sinkNumber > 0) {
463	            nextTokensPerBatch = static_cast<int32_t>(actSeqLensKv) - static_cast<int32_t>(constInfo.sinkNumber) -
464	                                 static_cast<int32_t>(actSeqLensQ) + static_cast<int32_t>(constInfo.nextToken);
465	        }
466	    } else if ((constInfo.sparseMode == fa_base_vector::DEFAULT_MASK) && constInfo.attenMaskFlag) {
467	        nextTokensPerBatch = constInfo.nextToken;
468	        preTokensPerBatch = static_cast<int32_t>(actSeqLensKv) - static_cast<int32_t>(actSeqLensQ) + constInfo.preToken;
469	    } else {
470	        nextTokensPerBatch = static_cast<int32_t>(actSeqLensKv) - static_cast<int32_t>(actSeqLensQ);
471	        if (constInfo.sinkNumber > 0) {
472	            if (constInfo.sparseMode == fa_base_vector::RIGHT_DOWN_CAUSAL &&
473	                static_cast<int32_t>(actSeqLensKv) - static_cast<int32_t>(constInfo.sinkNumber) <
474	                    static_cast<int32_t>(actSeqLensQ)) {
475	                nextTokensPerBatch = static_cast<int32_t>(actSeqLensKv) - static_cast<int32_t>(constInfo.sinkNumber) -
476	                                     static_cast<int32_t>(actSeqLensQ);
477	            } else if (constInfo.sparseMode == fa_base_vector::LEFT_UP_CAUSAL) {
478	                nextTokensPerBatch = constInfo.nextToken;
479	            }
480	        }
481	    }
482	}
483	template <typename FIAT> __aicore__ inline void FiaBlockVecFlashDecode<FIAT>::FlashDecode(FDparams &fd)
484	{
485	    if (blockIdx >= fd.usedVecNumOfFd) {
486	        return;
487	    }
488	    uint32_t fdTaskPrevEnd = (blockIdx > 0) ? fd.gS1IdxEndOfFdHead[blockIdx - 1] : 0; // 上一个核末尾是第几个规约
489	    uint32_t fdS1gOuterMPrevEnd =
490	        (blockIdx > 0) ? fd.gS1IdxEndOfFdHeadSplit[blockIdx - 1] : 0; // 上一个核末尾是该规约的第几个base行
491	    uint32_t fdTaskEnd = fd.gS1IdxEndOfFdHead[blockIdx];                 // 当前核的末尾是第几个规约任务
492	    uint32_t fdS1gOuterMEnd = fd.gS1IdxEndOfFdHeadSplit[blockIdx]; // 当前核的末尾是该规约的第几个base行
493	    uint32_t tmpFdS1gOuterMStart = (blockIdx > 0) ? fdS1gOuterMPrevEnd + 1 : 0; // 当前核从第几个base行开始
494	    uint32_t tmpFdS1gOuterMEnd = 0;
495	    uint32_t reduceGlobaLoop = 0;
496	    uint32_t reduceMLoop = 0;
497	
498	    for (uint32_t fdTaskId = fdTaskPrevEnd; fdTaskId <= fdTaskEnd; fdTaskId++) {
499	        tmpFdS1gOuterMEnd = (fdTaskId == fdTaskEnd) ? fdS1gOuterMEnd : (fd.gS1SplitNumOfFdHead[fdTaskId] - 1);
500	        taskInfo.bIdx = fd.bN2IdxOfFdHead[fdTaskId] / constInfo.kvHeadNum;
501	        taskInfo.n2Idx = fd.bN2IdxOfFdHead[fdTaskId] % constInfo.kvHeadNum;
502	        taskInfo.gS1Idx = fd.gS1IdxOfFdHead[fdTaskId] * constInfo.mBaseSize;
503	        taskInfo.actualCombineLoopSize = fd.s2SplitNumOfFdHead[fdTaskId]; // 当前规约任务kv方向有几份
504	
505	        uint64_t combineTaskPrefixSum = 0;
506	        for (int i = 0; i < fdTaskId; i++) {
507	            // 计算此前规约数据的累计份数，每一份的数据大小为 kvHeadNum * constInfo.tndSgBasicSize
508	            // |Task0-0|Task0-1|Task0-3|Task1-0|Task1-2|...|
509	            combineTaskPrefixSum += fd.s2SplitNumOfFdHead[i];
510	        }
511	
512	        uint64_t taskOffset = combineTaskPrefixSum * constInfo.mBaseSize;
513	
514	        for (uint32_t fdS1gOuterMIdx = tmpFdS1gOuterMStart; fdS1gOuterMIdx <= tmpFdS1gOuterMEnd;
515	             fdS1gOuterMIdx++) { // 左闭右闭
516	
517	            uint32_t actualGSplitSize = fd.gS1BaseSizeOfFd;
518	            if (fdS1gOuterMIdx == fd.gS1SplitNumOfFdHead[fdTaskId] - 1) {
519	                actualGSplitSize = fd.gS1LastPartSizeOfFdHead[fdTaskId];
520	            }
521	            uint32_t startRow = fdS1gOuterMIdx * fd.gS1BaseSizeOfFd;
522	
523	            LocalTensor<T> lseExp = fdLseExpBuf.Get<T>();
524	            LocalTensor<T> reduceOut = fdReduceBuf.Get<T>();
525	            CopyLseIn(startRow, actualGSplitSize, taskOffset, reduceMLoop);
526	
527	            LocalTensor<T> mm2Res;
528	            for (uint32_t preLoadIdx = 0; preLoadIdx < constInfo.preLoadNum; preLoadIdx++) {
529	                mm2Res = (reduceGlobaLoop + preLoadIdx) % 2 == 0 ? fdMm2ResBuf1.Get<T>() : fdMm2ResBuf2.Get<T>();
530	                WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_MM2RES_BUF1_FLAG + (reduceGlobaLoop + preLoadIdx) % 2);
531	                CopyAccumOutIn(mm2Res, preLoadIdx, taskOffset + startRow, actualGSplitSize);
532	                SetFlag<AscendC::HardEvent::MTE2_V>(SYNC_MM2RES_BUF1_FLAG + (reduceGlobaLoop + preLoadIdx) % 2);
533	            }
534	
535	            ComputeScaleValue(lseExp, startRow, actualGSplitSize, reduceMLoop);
536	            CalaPreNextTokens();
537	            //****************************************************************************************************** */
538	            if (constInfo.softmaxLseFlag) {
539	                // 新增 计算规约后的max和sum
540	                LocalTensor<T> lseMaxUb = fdLseMaxUbBuf.Get<T>();
541	                LocalTensor<T> lseSumUb = fdLseSumUbBuf.Get<T>();
542	                // 新增 最终LSE的计算lse = log(sum) + max
543	
544	                WaitFlag<HardEvent::MTE3_V>(SYNC_LSEOUTPUT_BUF_FLAG);
545	                LocalTensor<T> lseftMaxLseUb = fdLseUbBuf.Get<T>();
546	                fa_base_vector::ComputeSoftMaxLse(lseftMaxLseUb, lseSumUb, lseMaxUb, actualGSplitSize);
547	                // 判断是否行无效
548	                bool isInValidRowsFlag = fa_base_vector::IsExistInvalidRows(nextTokensPerBatch,
549	                                                                            preTokensPerBatch,
550	                                                                            constInfo.sparseMode,
551	                                                                            constInfo.attenMaskFlag,
552	                                                                            constInfo.isRowInvalid);
553	                if (isInValidRowsFlag) {
554	                    SoftMaxShapeInfo softmaxShapeInfo{static_cast<uint32_t>(actualGSplitSize),
555	                                                      static_cast<uint32_t>(fa_base_vector::FP32_BLOCK_ELEMENT_NUM),
556	                                                      static_cast<uint32_t>(actualGSplitSize),
557	                                                      static_cast<uint32_t>(fa_base_vector::FP32_BLOCK_ELEMENT_NUM)};
558	                    AdjustSoftMaxRes<T, T>(lseftMaxLseUb, lseMaxUb, negativeIntScalar, (T)3e+99, softmaxShapeInfo);
559	                }
560	                SetFlag<HardEvent::V_MTE3>(SYNC_LSEOUTPUT_BUF_FLAG);
561	                WaitFlag<HardEvent::V_MTE3>(SYNC_LSEOUTPUT_BUF_FLAG);
562	                uint32_t mOffset = taskInfo.gS1Idx + startRow;
563	                if (LAYOUT_T == FIA_LAYOUT::TND) {
564	                    uint32_t prefixBS1 = taskInfo.bIdx == 0U ? 0U : actualSeqLengthsGmQ.GetValue(taskInfo.bIdx - 1);
565	                    uint64_t bN2Offset = prefixBS1 * constInfo.qHeadNum + taskInfo.n2Idx * constInfo.gSize;
566	                    DataCopySoftmaxLseTND(softmaxLseGm, lseftMaxLseUb, bN2Offset, mOffset, actualGSplitSize, constInfo);
567	                } else if (LAYOUT_T == FIA_LAYOUT::NTD) {
568	                    uint32_t prefixBS1 = taskInfo.bIdx == 0U ? 0U : actualSeqLengthsGmQ.GetValue(taskInfo.bIdx - 1);
569	                    uint32_t s1Size = taskInfo.bIdx == 0U ? actualSeqLengthsGmQ.GetValue(0U)
570	                                                          : actualSeqLengthsGmQ.GetValue(taskInfo.bIdx) -
571	                                                                actualSeqLengthsGmQ.GetValue(taskInfo.bIdx - 1U);
572	                    uint64_t bN2Offset = prefixBS1 * constInfo.qHeadNum + taskInfo.n2Idx * constInfo.gSize;
573	                    DataCopySoftmaxLseNTD(
574	                        softmaxLseGm, lseftMaxLseUb, bN2Offset, mOffset, actualGSplitSize, constInfo, s1Size);
575	                } else if (LAYOUT_T == FIA_LAYOUT::BSND || LAYOUT_T == FIA_LAYOUT::BSH) {
576	                    uint64_t bN2Offset = taskInfo.bIdx * constInfo.qHeadNum * constInfo.qSeqSize +
577	                                         taskInfo.n2Idx * constInfo.gSize * constInfo.qSeqSize;
578	                    DataCopySoftmaxLseBSND(softmaxLseGm,
579	                                           lseftMaxLseUb,
580	                                           bN2Offset,
581	                                           mOffset,
582	                                           actualGSplitSize,
583	                                           constInfo,
584	                                           qActSeqLensParser,
585	                                           taskInfo.bIdx);
586	                } else { // BNSD
587	                    uint64_t bN2Offset = taskInfo.bIdx * constInfo.qHeadNum * constInfo.qSeqSize +
588	                                         taskInfo.n2Idx * constInfo.gSize * constInfo.qSeqSize;
589	                    DataCopySoftmaxLseBNSD<T, Q_MODE>(softmaxLseGm,
590	                                                      lseftMaxLseUb,
591	                                                      bN2Offset,
592	                                                      mOffset,
593	                                                      actualGSplitSize,
594	                                                      constInfo,
595	                                                      qActSeqLensParser,
596	                                                      taskInfo.bIdx);
597	                }
598	                SetFlag<HardEvent::MTE3_V>(SYNC_LSEOUTPUT_BUF_FLAG);
599	            }
600	
601	            SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_SUM_BUF1_FLAG + reduceMLoop % 2);
602	            SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_LSE_MAX_BUF1_FLAG + reduceMLoop % 2);
603	            //****************************************************************************************************** */
604	
605	            for (uint32_t i = 0; i < taskInfo.actualCombineLoopSize; i++) {
606	                mm2Res = reduceGlobaLoop % 2 == 0 ? fdMm2ResBuf1.Get<T>() : fdMm2ResBuf2.Get<T>();
607	                if (i >= constInfo.preLoadNum) {
608	                    WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_MM2RES_BUF1_FLAG + reduceGlobaLoop % 2);
609	                    CopyAccumOutIn(mm2Res, i, taskOffset + startRow, actualGSplitSize);
610	                    SetFlag<AscendC::HardEvent::MTE2_V>(SYNC_MM2RES_BUF1_FLAG + reduceGlobaLoop % 2);
611	                }
612	
613	                WaitFlag<AscendC::HardEvent::MTE2_V>(SYNC_MM2RES_BUF1_FLAG + reduceGlobaLoop % 2);
614	                ReduceFinalRes(reduceOut, mm2Res, lseExp, i, actualGSplitSize);
615	                SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_MM2RES_BUF1_FLAG + reduceGlobaLoop % 2);
616	                reduceGlobaLoop += 1;
617	            }
618	            CopyFinalResOut(reduceOut, startRow, actualGSplitSize);
619	            reduceMLoop += 1;
620	        }
621	        tmpFdS1gOuterMStart = 0;
622	    }
623	}
624	#endif

