307	template <typename FIAT>
308	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::Init(__gm__ uint8_t *query,
309	                                                        __gm__ uint8_t *key,
310	                                                        __gm__ uint8_t *value,
311	                                                        __gm__ uint8_t *pseShift,
312	                                                        __gm__ uint8_t *attenMask,
313	                                                        __gm__ uint8_t *actualSeqLengthsQ,
314	                                                        __gm__ uint8_t *actualSeqLengths,
315	                                                        __gm__ uint8_t *deqScale1,
316	                                                        __gm__ uint8_t *quantScale1,
317	                                                        __gm__ uint8_t *deqScale2,
318	                                                        __gm__ uint8_t *quantScale2,
319	                                                        __gm__ uint8_t *quantOffset2,
320	                                                        __gm__ uint8_t *antiquantScale,
321	                                                        __gm__ uint8_t *antiquantOffset,
322	                                                        __gm__ uint8_t *blockTable,
323	                                                        __gm__ uint8_t *queryPaddingSize,
324	                                                        __gm__ uint8_t *kvPaddingSize,
325	                                                        __gm__ uint8_t *keyAntiquantScale,
326	                                                        __gm__ uint8_t *keyAntiquantOffset,
327	                                                        __gm__ uint8_t *valueAntiquantScale,
328	                                                        __gm__ uint8_t *valueAntiquantOffset,
329	                                                        __gm__ uint8_t *queryRope,
330	                                                        __gm__ uint8_t *keyRope,
331	                                                        __gm__ uint8_t *keyRopeAntiquantScale,
332	                                                        __gm__ uint8_t *attentionOut,
333	                                                        __gm__ uint8_t *softmaxLse)
334	{
335	    uint32_t qkTensorD = constInfo.ropeSplitMode ? constInfo.headDim : (constInfo.headDim + constInfo.headDimRope);
336	
337	    // init global buffer
338	    queryGm.SetGlobalBuffer((__gm__ Q_T *)query);
339	    InitQBuffer(constInfo.batchSize,
340	                constInfo.kvHeadNum,
341	                constInfo.gSize,
342	                constInfo.qSeqSize,
343	                qkTensorD,
344	                actualSeqLengthsGmQ,
345	                constInfo.actualLenQDims,
346	                queryGmTensor,
347	                queryGm);
348	
349	    if (constInfo.ropeSplitMode) {
350	        // query rope
351	        qRopeGm.SetGlobalBuffer((__gm__ Q_T *)queryRope);
352	        InitQBuffer(constInfo.batchSize,
353	                    constInfo.kvHeadNum,
354	                    constInfo.gSize,
355	                    constInfo.qSeqSize,
356	                    constInfo.headDimRope,
357	                    actualSeqLengthsGmQ,
358	                    constInfo.actualLenQDims,
359	                    queryRopeGmTensor,
360	                    qRopeGm);
361	        // key rope
362	        keyRopeGm.SetGlobalBuffer((__gm__ KV_T *)keyRope);
363	        InitKVBuffer(constInfo.batchSize,
364	                     constInfo.kvSeqSize,
365	                     actualSeqLengthsGm,
366	                     constInfo.actualLenDims,
367	                     constInfo.kvHeadNum,
368	                     constInfo.kvCacheBlockSize,
369	                     constInfo.headDimRope,
370	                     keyRopeGmTensor,
371	                     keyRopeGm,
372	                     constInfo.keyRopeStride);
373	    }
374	
375	    keyPtr = key;
376	    valuePtr = value;
377	    // batch连续时,只需要初始化一次;不连续时,需要在使用时根据batchIdx初始化
378	    if (constInfo.batchContinuous) {
379	        InitKeyGm(0);
380	        InitKVBuffer(constInfo.batchSize,
381	                     constInfo.kvSeqSize,
382	                     actualSeqLengthsGm,
383	                     constInfo.actualLenDims,
384	                     constInfo.kvHeadNum,
385	                     constInfo.kvCacheBlockSize,
386	                     qkTensorD,
387	                     keyGmTensor,
388	                     keyGm,
389	                     constInfo.keyStride);
390	
391	        InitValueGm(0);
392	        InitKVBuffer(constInfo.batchSize,
393	                     constInfo.kvSeqSize,
394	                     actualSeqLengthsGm,
395	                     constInfo.actualLenDims,
396	                     constInfo.kvHeadNum,
397	                     constInfo.kvCacheBlockSize,
398	                     constInfo.headDim,
399	                     valueGmTensor,
400	                     valueGm,
401	                     constInfo.valueStride);
402	    }
403	
404	    if (constInfo.actualLenQDims != 0) {
405	        actualSeqLengthsGmQ.SetGlobalBuffer((__gm__ uint64_t *)actualSeqLengthsQ, constInfo.actualLenQDims);
406	        this->actualSequenceLengthsQ = actualSeqLengthsQ;
407	    }
408	    if (constInfo.actualLenDims != 0) {
409	        actualSeqLengthsGm.SetGlobalBuffer((__gm__ uint64_t *)actualSeqLengths, constInfo.actualLenDims);
410	        this->actualSeqLengths = actualSeqLengths;
411	    }
412	    if constexpr (PAGE_ATTENTION) {
413	        blockTableGm.SetGlobalBuffer((__gm__ int32_t *)blockTable);
414	    }
415	}
