417	template <typename FIAT>
418	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitQBuffer(uint32_t batchSize,
419	                                                               uint32_t kvHeadNum,
420	                                                               uint32_t gSize,
421	                                                               uint32_t qSeqSize,
422	                                                               uint32_t headDim,
423	                                                               GlobalTensor<uint64_t> actualSeqLengthsGmQ,
424	                                                               uint32_t actualLenQDims,
425	                                                               FaGmTensor<Q_T, Q_FORMAT> &qGmTensor,
426	                                                               GlobalTensor<Q_T> &qGm)
427	{
428	    qGmTensor.gmTensor = qGm;
429	    if constexpr (GmLayoutParams<Q_FORMAT>::CATEGORY == FormatCategory::GM_Q_OUT_BNGSD) {
430	        qGmTensor.offsetCalculator.Init(
431	            batchSize, kvHeadNum, gSize, qSeqSize, headDim, actualSeqLengthsGmQ, actualLenQDims);
432	    } else if constexpr (GmLayoutParams<Q_FORMAT>::CATEGORY == FormatCategory::GM_Q_OUT_TND) {
433	        qGmTensor.offsetCalculator.Init(kvHeadNum, gSize, headDim, actualSeqLengthsGmQ, actualLenQDims);
434	    }
435	}
