437	template <typename FIAT>
438	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitKVBuffer(uint32_t batchSize,
439	                                                                uint32_t kvSeqSize,
440	                                                                GlobalTensor<uint64_t> actualSeqLengthsGmQ,
441	                                                                uint32_t actualLenDims,
442	                                                                uint32_t kvHeadNum,
443	                                                                uint32_t kvCacheBlockSize,
444	                                                                uint32_t headDim,
445	                                                                FaGmTensor<KV_T, KV_FORMAT> &kvGmTensor,
446	                                                                GlobalTensor<KV_T> &kvGm,
447	                                                                uint64_t *stride)
448	{
449	    kvGmTensor.gmTensor = kvGm;
450	    if constexpr (PAGE_ATTENTION) {
451	        if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_PA_BNBD) {
452	            kvGmTensor.offsetCalculator.Init(
453	                kvHeadNum, kvCacheBlockSize, headDim, blockTableGm, constInfo.maxBlockNumPerBatch, stride);
454	        } else if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_PA_NZ) {
455	            uint32_t d0 = 32 / sizeof(KV_T);
456	            uint32_t d1 = headDim / d0;
457	            kvGmTensor.offsetCalculator.Init(
458	                kvHeadNum, kvCacheBlockSize, d1, d0, blockTableGm, constInfo.maxBlockNumPerBatch, stride);
459	        }
460	    } else {
461	        if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_BNSD) {
462	            kvGmTensor.offsetCalculator.Init(batchSize, kvHeadNum, kvSeqSize, headDim);
463	        } else if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_TND) {
464	            kvGmTensor.offsetCalculator.Init(kvHeadNum, headDim, actualSeqLengthsGm, actualLenDims);
465	        }
466	    }
467	}
