553	template <typename FIAT>
554	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::CopyKeyToL1(const RunInfo &info,
555	                                                               uint32_t kSize,
556	                                                               uint32_t kStart,
557	                                                               uint32_t kDealSize,
558	                                                               uint32_t nSize,
559	                                                               uint32_t nStart,
560	                                                               uint32_t nDealSize,
561	                                                               uint32_t nopeDealSize,
562	                                                               uint32_t ropeDealSize,
563	                                                               uint64_t l1Offset)
564	{
565	    if (nopeDealSize > 0) {
566	        FaL1Tensor<KV_T, L1Format::NZ> dstTensor{.tensor = kvL1Tensor[l1Offset], .rowCount = Align(nDealSize, 16U)};
567	        GmKvCoord gmCoord{.bIdx = constInfo.batchContinuous ? info.bIdx : 0,
568	                          .n2Idx = info.n2Idx,
569	                          .s2Idx = info.s2Idx * constInfo.s2BaseSize + nStart,
570	                          .dIdx = kStart,
571	                          .s2DealSize = nDealSize,
572	                          .dDealSize = nopeDealSize};
573	        copyKvGmToL1(dstTensor, keyGmTensor, gmCoord);
574	    }
575	    if (ropeDealSize > 0) {
576	        // nopeDealSize需要按照32B对齐, 否则这里取偏移的方式错误, 并且当前分段拷贝存在问题
577	        FaL1Tensor<KV_T, L1Format::NZ> dstTensor{
578	            .tensor = kvL1Tensor[l1Offset + Align(nopeDealSize, 16U) * Align(nDealSize, 16U)],
579	            .rowCount = Align(nDealSize, 16U)};
580	        GmKvCoord gmCoord{.bIdx = constInfo.batchContinuous ? info.bIdx : 0,
581	                          .n2Idx = info.n2Idx,
582	                          .s2Idx = info.s2Idx * constInfo.s2BaseSize + nStart,
583	                          .dIdx = kStart + nopeDealSize - static_cast<uint32_t>(constInfo.headDim),
584	                          .s2DealSize = nDealSize,
585	                          .dDealSize = ropeDealSize};
586	        copyKvGmToL1(dstTensor, keyRopeGmTensor, gmCoord);
587	    }
588	}
