590	template <typename FIAT>
591	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::CopyQDealSizeToL1(uint32_t DealSize,
592	                                                                     uint64_t queryL1Offset,
593	                                                                     uint32_t mActSizeAlign,
594	                                                                     uint32_t bIdx,
