607	template <typename FIAT>
608	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::CopyQGmToL1(uint32_t nopeDealSize,
609	                                                               uint32_t ropeDealSize,
610	                                                               uint32_t mActSizeAlign,
611	                                                               uint32_t bIdx,
612	                                                               uint32_t n2Idx,
613	                                                               uint32_t gS1Idx,
614	                                                               uint32_t kStart,
615	                                                               uint32_t mActSize)
616	{
617	    uint64_t queryL1BaseOffset = (qpBufId % 2) * (L1_QP_SIZE / sizeof(Q_T));
618	    if (nopeDealSize > 0) {
619	        CopyQDealSizeToL1(
620	            nopeDealSize, queryL1BaseOffset, mActSizeAlign, bIdx, n2Idx, gS1Idx, kStart, mActSize, queryGmTensor);
621	    }
622	    uint64_t queryRopeL1Offset = queryL1BaseOffset + Align(nopeDealSize, 16U) * mActSizeAlign;
623	    if (ropeDealSize > 0) {
624	        uint32_t ropeKStart = kStart + nopeDealSize - static_cast<uint32_t>(constInfo.headDim);
625	        CopyQDealSizeToL1(ropeDealSize,
626	                          queryRopeL1Offset,
627	                          mActSizeAlign,
628	                          bIdx,
629	                          n2Idx,
630	                          gS1Idx,
631	                          ropeKStart,
632	                          mActSize,
633	                          queryRopeGmTensor);
634	    }
635	}
