637	template <typename FIAT>
638	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::DealMm1SingleMKN(const RunInfo &info,
639	                                                                    uint32_t mSize,
640	                                                                    uint32_t mStart,
641	                                                                    uint32_t mDealSize,
642	                                                                    uint32_t kSize,
643	                                                                    uint32_t kStart,
644	                                                                    uint32_t kDealSize,
645	                                                                    uint32_t nSize,
646	                                                                    uint32_t nStart,
647	                                                                    uint32_t nDealSize,
648	                                                                    uint32_t nopeDealSize,
649	                                                                    uint32_t ropeDealSize)
650	{
651	    constexpr uint32_t M_BASE = 128;
652	    constexpr uint32_t K_BASE = 128;
653	
654	    WaitFlag<HardEvent::MTE1_MTE2>(KV_EVENT0 + kvBufId % 2);
655	
656	    uint64_t l1Offset = (kvBufId % 2) * (L1_KV_SIZE / sizeof(KV_T));
657	    CopyKeyToL1(info, kSize, kStart, kDealSize, nSize, nStart, nDealSize, nopeDealSize, ropeDealSize, l1Offset);
658	
659	    SetFlag<HardEvent::MTE2_MTE1>(KV_EVENT0 + kvBufId % 2);
660	    WaitFlag<HardEvent::MTE2_MTE1>(KV_EVENT0 + kvBufId % 2);
661	    for (uint32_t m = 0; m < mDealSize; m += M_BASE) {
662	        uint32_t mActSize = M_BASE;
663	        if (m + M_BASE > mDealSize) {
664	            mActSize = mDealSize - m;
665	        }
666	        uint32_t mActSizeAlign = Align(mActSize, 16U);
667	        // QK 首次S2循环拷贝Q
668	        if (nStart == 0) {
669	            WaitFlag<HardEvent::MTE1_MTE2>(QP_EVENT0 + qpBufId % 2);
670	            uint64_t queryL1BaseOffset = (qpBufId % 2) * (L1_QP_SIZE / sizeof(Q_T));
671	            // 根据nope和rope上需要拷贝的数据长度分别执行Copy动作
672	            uint32_t gS1Idx = info.gS1Idx + mStart + m;
673	            CopyQGmToL1(nopeDealSize, ropeDealSize, mActSizeAlign, info.bIdx, info.n2Idx, gS1Idx, kStart, mActSize);
674	            SetFlag<HardEvent::MTE2_MTE1>(QP_EVENT0 + qpBufId % 2);
675	            WaitFlag<HardEvent::MTE2_MTE1>(QP_EVENT0 + qpBufId % 2);
676	        } else {
677	            if (m == 0) {
678	                qpBufId = (qpBufId + ((mDealSize + M_BASE - 1) / M_BASE)) % 2;
679	            }
680	        }
681	
682	        // matmul k
683	        WaitFlag<HardEvent::FIX_M>(L0C_EVENT0 + l0cBufId % 2);
684	        LocalTensor<T> cL0Tensor = cL0TensorPingPong[(l0cBufId % 2) * (L0C_PP_SIZE / sizeof(MM_OUT_T))];
685	        uint32_t kDealSizeAlign = Align(nopeDealSize, 16U) + Align(ropeDealSize, 16U);
686	        for (uint32_t k = 0; k < kDealSizeAlign; k += K_BASE) {
687	            uint32_t kActSize = K_BASE;
688	            if (k + K_BASE > kDealSizeAlign) {
689	                kActSize = kDealSizeAlign - k;
690	            }
691	            uint32_t kActSizeAlign = Align(kActSize, 16U);
692	            WaitFlag<HardEvent::M_MTE1>(L0AB_EVENT0 + l0abBufId % 2);
693	            LocalTensor<Q_T> aL0Tensor = aL0TensorPingPong[(l0abBufId % 2) * (L0A_PP_SIZE / sizeof(Q_T))];
694	            LocalTensor<KV_T> bL0Tensor = bL0TensorPingPong[(l0abBufId % 2) * (L0B_PP_SIZE / sizeof(KV_T))];
695	            // LoadAToL0
696	            {
697	                uint64_t qL1Offset = (qpBufId % 2) * (L1_QP_SIZE / sizeof(Q_T)) + k * mActSizeAlign;
698	                uint32_t mLoop = mActSizeAlign / 16;
699	                for (uint32_t i = 0; i < mLoop; i++) {
700	                    LoadData2DParams loadData2DParams;
701	                    loadData2DParams.startIndex = i;
702	                    loadData2DParams.repeatTimes = kActSizeAlign / 16;
703	                    loadData2DParams.srcStride = mActSizeAlign / 16;
704	                    loadData2DParams.dstGap = 0;
705	                    loadData2DParams.ifTranspose = false;
706	                    ;
707	                    LoadData(aL0Tensor[16 * i * kActSizeAlign], qpL1Tensor[qL1Offset], loadData2DParams);
708	                }
709	            }
710	            // LoadBToL0
711	            {
712	                uint64_t kL1Offset = (kvBufId % 2) * (L1_KV_SIZE / sizeof(KV_T)) + k * Align(nDealSize, 16U);
713	                LoadData2DParams loadData2DParams;
714	                loadData2DParams.startIndex = 0;
715	                loadData2DParams.repeatTimes = (kActSizeAlign / 16) * (Align(nDealSize, 16U) / 16);
716	                loadData2DParams.srcStride = 1;
717	                loadData2DParams.dstGap = 0;
718	                loadData2DParams.ifTranspose = false;
719	                LoadData(bL0Tensor, kvL1Tensor[kL1Offset], loadData2DParams);
720	            }
721	            SetFlag<HardEvent::MTE1_M>(L0AB_EVENT0 + l0abBufId % 2);
722	            WaitFlag<HardEvent::MTE1_M>(L0AB_EVENT0 + l0abBufId % 2);
723	            // MMAD
724	            {
725	                MmadParams mmadParams;
726	                mmadParams.m = mActSize;
727	                if (mmadParams.m == 1) {
728	                    mmadParams.m = 16;
729	                }
730	                mmadParams.n = nDealSize;
731	                mmadParams.k = kActSize;
732	                mmadParams.cmatrixInitVal = (k == 0);
733	                mmadParams.cmatrixSource = false;
734	                Mmad(cL0Tensor, aL0Tensor, bL0Tensor, mmadParams);
735	            }
736	            AscendC::PipeBarrier<PIPE_M>();
737	            SetFlag<HardEvent::M_MTE1>(L0AB_EVENT0 + l0abBufId % 2);
738	            l0abBufId = (l0abBufId + 1) % 2;
739	        }
740	        SetFlag<HardEvent::M_FIX>(L0C_EVENT0 + l0cBufId % 2);
741	        WaitFlag<HardEvent::M_FIX>(L0C_EVENT0 + l0cBufId % 2);
742	        // FIXPIPE
743	        {
744	            if (kStart != 0) {
745	                SetAtomicAdd<MM_OUT_T>();
746	            }
747	            FixpipeParamsV220 fixParams;
748	            fixParams.mSize = mActSize;
749	            fixParams.nSize = nDealSize;
750	            fixParams.srcStride = mActSizeAlign;
751	            fixParams.dstStride = info.actualSingleProcessSInnerSizeAlign; // mm1ResGm两行之间的间隔
752	            fixParams.ndNum = 1;
753	            uint64_t mm1ResGmOffset = (info.loop % (constInfo.preLoadNum)) * constInfo.mmResUbSize +
754	                                      (mStart + m) * info.actualSingleProcessSInnerSizeAlign + // m方向上偏移
755	                                      nStart; // n方向上偏移nStart个元素
756	            Fixpipe(mm1ResGm[mm1ResGmOffset], cL0Tensor, fixParams);
757	            if (kStart != 0) {
758	                SetAtomicNone();
759	            }
760	        }
761	        SetFlag<HardEvent::FIX_M>(L0C_EVENT0 + l0cBufId % 2);
762	        l0cBufId = (l0cBufId + 1) % 2;
763	
764	        if (nStart + nDealSize >= nSize) {
765	            SetFlag<HardEvent::MTE1_MTE2>(QP_EVENT0 + qpBufId % 2);
766	        }
767	        qpBufId = (qpBufId + 1) % 2;
768	    }
769	    SetFlag<HardEvent::MTE1_MTE2>(KV_EVENT0 + kvBufId % 2);
770	    kvBufId = (kvBufId + 1) % 2;
771	}
772	
773	template <typename FIAT>
774	__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::DealMm2SingleMKN(const RunInfo &info,
775	                                                                    uint32_t mSize,
776	                                                                    uint32_t mStart,
777	                                                                    uint32_t mDealSize,
778	                                                                    uint32_t kSize,
779	                                                                    uint32_t kStart,
780	                                                                    uint32_t kDealSize,
781	                                                                    uint32_t nSize,
782	                                                                    uint32_t nStart,
783	                                                                    uint32_t nDealSize)
784	{
785	    constexpr uint32_t M_BASE = 128;
786	    constexpr uint32_t K_BASE = 128;
787	
788	    WaitFlag<HardEvent::MTE1_MTE2>(KV_EVENT0 + kvBufId % 2);
789	
790	    uint64_t l1Offset = (kvBufId % 2) * (L1_KV_SIZE / sizeof(KV_T));
791	    FaL1Tensor<KV_T, L1Format::NZ> dstTensor{.tensor = kvL1Tensor[l1Offset], .rowCount = (kDealSize + 15) / 16 * 16};
792	    GmKvCoord gmCoord{.bIdx = constInfo.batchContinuous ? info.bIdx : 0,
793	                      .n2Idx = info.n2Idx,
794	                      .s2Idx = info.s2Idx * constInfo.s2BaseSize + kStart,
795	                      .dIdx = nStart,
796	                      .s2DealSize = kDealSize,
797	                      .dDealSize = nDealSize};
798	    copyKvGmToL1(dstTensor, valueGmTensor, gmCoord);
799	
800	    SetFlag<HardEvent::MTE2_MTE1>(KV_EVENT0 + kvBufId % 2);
801	    WaitFlag<HardEvent::MTE2_MTE1>(KV_EVENT0 + kvBufId % 2);
802	    for (uint32_t m = 0; m < mDealSize; m += M_BASE) {
803	        uint32_t mActSize = M_BASE;
804	        if (m + M_BASE > mDealSize) {
805	            mActSize = mDealSize - m;
806	        }
807	        uint32_t mActSizeAlign = Align(mActSize, 16U);
808	        if (nStart == 0) {
809	            WaitFlag<HardEvent::MTE1_MTE2>(QP_EVENT0 + qpBufId % 2);
810	            // CopySoftmaxResGmToL1
811	            {
812	                Nd2NzParams nd2nzPara;
813	                nd2nzPara.ndNum = 1;
814	                nd2nzPara.nValue = mActSize; // 行数
815	                nd2nzPara.dValue = kDealSize;
816	                nd2nzPara.srcDValue = info.actualSingleProcessSInnerSizeAlign;
817	                nd2nzPara.dstNzC0Stride = (mActSize + 15) / 16 * 16; // 对齐到16 单位block
818	                nd2nzPara.dstNzNStride = 1;
819	                nd2nzPara.srcNdMatrixStride = 0;
820	                nd2nzPara.dstNzMatrixStride = 0;
821	
822	                uint64_t softmaxResL1BaseOffset = (qpBufId % 2) * (L1_QP_SIZE / sizeof(Q_T));
823	                uint64_t offset = (info.loop % (constInfo.preLoadNum)) * constInfo.mmResUbSize +
824	                                  (mStart + m) * info.actualSingleProcessSInnerSizeAlign + kStart;
825	                DataCopy(qpL1Tensor[softmaxResL1BaseOffset], vec1ResGm[offset], nd2nzPara);
826	            }
827	            SetFlag<HardEvent::MTE2_MTE1>(QP_EVENT0 + qpBufId % 2);
828	            WaitFlag<HardEvent::MTE2_MTE1>(QP_EVENT0 + qpBufId % 2);
829	        } else {
830	            if (m == 0) {
831	                qpBufId = (qpBufId + ((mDealSize + M_BASE - 1) / M_BASE)) % 2;
832	            }
833	        }
834	
835	        WaitFlag<HardEvent::FIX_M>(L0C_EVENT0 + l0cBufId % 2);
836	        LocalTensor<T> cL0Tensor = cL0TensorPingPong[(l0cBufId % 2) * (L0C_PP_SIZE / sizeof(MM_OUT_T))];
837	        // matmul k
838	        for (uint32_t k = 0; k < kDealSize; k += K_BASE) {
839	            uint32_t kActSize = K_BASE;
840	            if (k + K_BASE > kDealSize) {
841	                kActSize = kDealSize - k;
842	            }
843	
844	            WaitFlag<HardEvent::M_MTE1>(L0AB_EVENT0 + l0abBufId % 2);
845	            uint32_t kActSizeAlign = Align(kActSize, 16U);
846	            LocalTensor<Q_T> aL0Tensor = aL0TensorPingPong[(l0abBufId % 2) * (L0A_PP_SIZE / sizeof(Q_T))];
847	            LocalTensor<KV_T> bL0Tensor = bL0TensorPingPong[(l0abBufId % 2) * (L0B_PP_SIZE / sizeof(KV_T))];
848	            // LoadAToL0
849	            {
850	                uint64_t qL1Offset = (qpBufId % 2) * (L1_QP_SIZE / sizeof(Q_T)) + k * mActSizeAlign;
851	                uint32_t mLoop = mActSizeAlign / 16;
852	                for (uint32_t i = 0; i < mLoop; i++) {
853	                    LoadData2DParams loadData2DParams;
854	                    loadData2DParams.startIndex = i;
855	                    loadData2DParams.repeatTimes = kActSizeAlign / 16;
856	                    loadData2DParams.srcStride = mActSizeAlign / 16;
857	                    loadData2DParams.dstGap = 0;
858	                    loadData2DParams.ifTranspose = false;
859	                    LoadData(aL0Tensor[16 * i * kActSizeAlign], qpL1Tensor[qL1Offset], loadData2DParams);
860	                }
861	            }
862	            // LoadBToL0
863	            {
864	                uint64_t kL1Offset = (kvBufId % 2) * (L1_KV_SIZE / sizeof(KV_T)) + k * 16U;
865	                uint32_t kLoop = kActSizeAlign / 16;
866	                for (uint32_t i = 0; i < kLoop; i++) {
867	                    LoadData2DParams loadData2DParams;
868	                    loadData2DParams.startIndex = i;
869	                    loadData2DParams.repeatTimes = Align(nDealSize, 16U) / 16;
870	                    loadData2DParams.srcStride = Align(kDealSize, 16U) / 16;
871	                    loadData2DParams.dstGap = 0;
872	                    loadData2DParams.ifTranspose = true;
873	                    LoadData(bL0Tensor[16 * i * Align(nDealSize, 16U)], kvL1Tensor[kL1Offset], loadData2DParams);
874	                }
875	            }
876	            SetFlag<HardEvent::MTE1_M>(L0AB_EVENT0 + l0abBufId % 2);
877	            WaitFlag<HardEvent::MTE1_M>(L0AB_EVENT0 + l0abBufId % 2);
878	            // MMAD
879	            {
880	                MmadParams mmadParams;
881	                mmadParams.m = mActSize;
882	                if (mmadParams.m == 1) {
883	                    mmadParams.m = 16;
884	                }
885	                mmadParams.n = nDealSize;
886	                mmadParams.k = kActSize;
887	                mmadParams.cmatrixInitVal = (k == 0);
888	                mmadParams.cmatrixSource = false;
889	                Mmad(cL0Tensor, aL0Tensor, bL0Tensor, mmadParams);
890	            }
891	            AscendC::PipeBarrier<PIPE_M>();
892	            SetFlag<HardEvent::M_MTE1>(L0AB_EVENT0 + l0abBufId % 2);
893	            l0abBufId = (l0abBufId + 1) % 2;
894	        }
895	        SetFlag<HardEvent::M_FIX>(L0C_EVENT0 + l0cBufId % 2);
896	        WaitFlag<HardEvent::M_FIX>(L0C_EVENT0 + l0cBufId % 2);
897	        // FIXPIPE
898	        {
899	            if (kStart != 0) {
900	                SetAtomicAdd<MM_OUT_T>();
901	            }
902	            FixpipeParamsV220 fixParams;
903	            fixParams.mSize = mActSize;
904	            fixParams.nSize = nDealSize;
905	            fixParams.srcStride = mActSizeAlign;
906	            fixParams.dstStride = constInfo.headDimAlign; // mm2ResGm两行之间的间隔
907	            fixParams.ndNum = 1;
908	
909	            uint64_t mm2ResGmOffset = (info.loop % (constInfo.preLoadNum)) * constInfo.bmm2ResUbSize +
910	                                      (mStart + m) * constInfo.headDimAlign + // m方向上偏移
911	                                      nStart; // n方向上偏移nStart个元素
912	            Fixpipe(mm2ResGm[mm2ResGmOffset], cL0Tensor, fixParams);
913	            if (kStart != 0) {
914	                SetAtomicNone();
915	            }
916	        }
917	        SetFlag<HardEvent::FIX_M>(L0C_EVENT0 + l0cBufId % 2);
918	        l0cBufId = (l0cBufId + 1) % 2;
919	
920	        if (nStart + nDealSize >= nSize) {
921	            SetFlag<HardEvent::MTE1_MTE2>(QP_EVENT0 + qpBufId % 2);
922	        }
923	        qpBufId = (qpBufId + 1) % 2;
924	    }
925	    SetFlag<HardEvent::MTE1_MTE2>(KV_EVENT0 + kvBufId % 2);
926	    kvBufId = (kvBufId + 1) % 2;
927	}
928	
929	template <typename FIAT> __aicore__ inline void FiaBlockCubeNonQuant<FIAT>::ComputeMm1(const RunInfo &info)
930	{
931	    if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_BNSD) {
932	        if (info.isChangeBatch) {
933	            UpdateKey(info.bIdx);
934	        }
935	    }
936	    constexpr uint32_t M_SPLIT_SIZE = 256;
937	    constexpr uint32_t K_SPLIT_SIZE = 512;
938	    constexpr uint32_t N_SPLIT_SIZE = 128;
939	
940	    uint32_t mSize = info.actMBaseSize;
941	    uint32_t kSize = constInfo.headDim + constInfo.headDimRope;
942	    uint32_t nSize = info.actualSingleProcessSInnerSize;
943	
944	    if (constInfo.ropeSplitMode) {
945	        kSize = Align(constInfo.headDim, 16UL) + constInfo.headDimRope;
946	    }
947	    for (uint32_t kStart = 0; kStart < kSize; kStart += K_SPLIT_SIZE) {
948	        uint32_t kDealSize = K_SPLIT_SIZE;
949	        if (kStart + K_SPLIT_SIZE > kSize) {
950	            kDealSize = kSize - kStart;
951	        }
952	
953	        // 适配ROPE分离模式, 需要根据D的起始点和D方向拷贝长度, 拆分出需要在nope和rope上分别在D方向上拷贝的数据长度
954	        uint32_t nopeDealSize = kDealSize;
955	        uint32_t ropeDealSize = 0;
956	        if (constInfo.ropeSplitMode) {
957	            if ((kStart < constInfo.headDim) && (kStart + kDealSize > constInfo.headDim)) {
958	                nopeDealSize = constInfo.headDim - kStart;
959	                // kDealSize -= Align(constInfo.headDim, 16UL) - constInfo.headDim;
960	                ropeDealSize = kStart + kDealSize - Align(constInfo.headDim, 16UL);
961	            } else if (kStart >= constInfo.headDim) {
962	                nopeDealSize = 0;
963	                ropeDealSize = kDealSize;
964	            }
965	        }
966	
967	        for (uint32_t mStart = 0; mStart < mSize; mStart += M_SPLIT_SIZE) {
968	            uint32_t mDealSize = M_SPLIT_SIZE;
969	            if (mStart + M_SPLIT_SIZE > mSize) {
970	                mDealSize = mSize - mStart;
971	            }
972	
973	            for (uint32_t nStart = 0; nStart < nSize; nStart += N_SPLIT_SIZE) {
974	                uint32_t nDealSize = N_SPLIT_SIZE;
975	                if (nStart + N_SPLIT_SIZE > nSize) {
976	                    nDealSize = nSize - nStart;
977	                }
978	
979	                DealMm1SingleMKN(info,
980	                                 mSize,
981	                                 mStart,
982	                                 mDealSize,
983	                                 kSize,
984	                                 kStart,
985	                                 kDealSize,
986	                                 nSize,
987	                                 nStart,
988	                                 nDealSize,
989	                                 nopeDealSize,
990	                                 ropeDealSize);
991	            }
992	        }
993	    }
994	    CrossCoreSetFlag<ConstInfo::FIA_SYNC_MODE2, PIPE_FIX>(constInfo.syncC1V1);
995	}
996	
997	template <typename FIAT> __aicore__ inline void FiaBlockCubeNonQuant<FIAT>::ComputeMm2(const RunInfo &info)
998	{
999	    if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_BNSD) {
1000	        if (info.isChangeBatch) {
1001	            UpdateValue(info.bIdx);
1002	        }
1003	    }
1004	    CrossCoreWaitFlag(constInfo.syncV1C2);
1005	
1006	    constexpr uint32_t M_SPLIT_SIZE = 256;
1007	    constexpr uint32_t K_SPLIT_SIZE = 512;
1008	    constexpr uint32_t N_SPLIT_SIZE = 128;
1009	
1010	    uint32_t mSize = info.actMBaseSize;
1011	    uint32_t kSize = info.actualSingleProcessSInnerSize;
1012	    uint32_t nSize = constInfo.headDim;
1013	    for (uint32_t kStart = 0; kStart < kSize; kStart += K_SPLIT_SIZE) {
1014	        uint32_t kDealSize = K_SPLIT_SIZE;
1015	        if (kStart + K_SPLIT_SIZE > kSize) {
1016	            kDealSize = kSize - kStart;
1017	        }
1018	
1019	        for (uint32_t mStart = 0; mStart < mSize; mStart += M_SPLIT_SIZE) {
1020	            uint32_t mDealSize = M_SPLIT_SIZE;
1021	            if (mStart + M_SPLIT_SIZE > mSize) {
1022	                mDealSize = mSize - mStart;
1023	            }
1024	
1025	            for (uint32_t nStart = 0; nStart < nSize; nStart += N_SPLIT_SIZE) {
1026	                uint32_t nDealSize = N_SPLIT_SIZE;
1027	                if (nStart + N_SPLIT_SIZE > nSize) {
1028	                    nDealSize = nSize - nStart;
1029	                }
1030	
1031	                DealMm2SingleMKN(info, mSize, mStart, mDealSize, kSize, kStart, kDealSize, nSize, nStart, nDealSize);
1032	            }
1033	        }
1034	    }
1035	
1036	    CrossCoreSetFlag<ConstInfo::FIA_SYNC_MODE2, PIPE_FIX>(constInfo.syncC2V2);
1037	}
1038	
1039	#endif
