/*!
 * \file fia_block_cube_nonquant_sink.h
 * \brief support all headDim and M
 */
#ifndef FIA_BLOCK_CUBE_NONQUANT_SINK_H
#define FIA_BLOCK_CUBE_NONQUANT_SINK_H

#include "kernel_operator.h"
#include "kernel_operator_list_tensor_intf.h"
#include "kernel_tiling/kernel_tiling.h"
#include "lib/matmul_intf.h"
#include "lib/matrix/matmul/tiling.h"
#include "../common/op_kernel/fia_public_define.h"
#include "../common/op_kernel/memory_copy.h"

using namespace AttentionCommon;
using AscendC::CrossCoreSetFlag;
using AscendC::CrossCoreWaitFlag;

template <typename FIAT> class FiaBlockCubeNonQuant {
  public:
    // 中间计算数据类型为float, 高精度模式
    using T = float;
    using N_UPDATE_T = int32_t;

    using Q_T = typename FIAT::queryType;
    using KV_T = typename FIAT::kvType;
    using OUT_T = typename FIAT::outputType;
    using ORIGIN_T = typename FIAT::orginalType;
    static constexpr bool PAGE_ATTENTION = FIAT::pageAttention;
    static constexpr bool KV_CONTINUOUS = FIAT::kvContinuous;
    static constexpr bool FLASH_DECODE = FIAT::flashDecode;
    static constexpr FIA_LAYOUT LAYOUT_T = FIAT::layout;
    static constexpr FIA_LAYOUT KV_LAYOUT_T = FIAT::kvLayout;
    static constexpr uint8_t PER_CHANNEL_MODE = 0; // 伪量化: K V per-channel
    static constexpr uint8_t PER_TOKEN_MODE = 1; // 伪量化: K V per-token
    static constexpr uint8_t PER_CHANNEL_TOKEN_MODE = 2; // 伪量化: K per-channel and V per-token
    static constexpr uint8_t ANTIQUANT_MODE = FIAT::antiquantMode;
    // static constexpr bool SHARED_PREFIX = FIAT::sharedPrefix;

    static constexpr GmFormat Q_FORMAT = GetQueryGmFormat<LAYOUT_T>();
    static constexpr GmFormat KV_FORMAT = GetKVFormat<KV_LAYOUT_T, PAGE_ATTENTION>();

    static constexpr bool ANTIQUANT = !IsSameType<Q_T, KV_T>::value;
    static constexpr bool KVINT4 = IsSameType<KV_T, int4b_t>::value;
    static constexpr bool QUANT = (IsSameType<Q_T, KV_T>::value && IsSameType<KV_T, int8_t>::value);
    static constexpr bool ANTIQUANT_PER_CHANNEL_TOKEN = (ANTIQUANT && (ANTIQUANT_MODE == PER_CHANNEL_TOKEN_MODE));
    static constexpr bool ANTIQUANT_PER_TOKEN = (ANTIQUANT && (ANTIQUANT_MODE == PER_TOKEN_MODE));
    static constexpr bool ANTIQUANT_PER_CHANNEL = (ANTIQUANT && (ANTIQUANT_MODE == PER_CHANNEL_MODE));
    using ANTIQ_PARAMS_T = typename AscendC::Conditional<ANTIQUANT_PER_TOKEN, T, Q_T>::type;
    // define pse datetype
    using pseShiftType = typename AscendC::Conditional<AscendC::IsSameType<Q_T, int8_t>::value, half, Q_T>::type;
    // 后接量化的条件需要重新审视
    static constexpr bool POST_QUANT = IsSameType<OUT_T, int8_t>::value;
    using MM_OUT_T = typename AscendC::Conditional<(ANTIQUANT || QUANT), int32_t, T>::type;
    __aicore__ inline FiaBlockCubeNonQuant(){};
    __aicore__ inline void InitParams(const ConstInfo &constInfo);
    __aicore__ inline void Init(__gm__ uint8_t *query,
                                __gm__ uint8_t *key,
                                __gm__ uint8_t *value,
                                __gm__ uint8_t *pseShift,
                                __gm__ uint8_t *attenMask,
                                __gm__ uint8_t *actualSeqLengthsQ,
                                __gm__ uint8_t *actualSeqLengths,
                                __gm__ uint8_t *deqScale1,
                                __gm__ uint8_t *quantScale1,
                                __gm__ uint8_t *deqScale2,
                                __gm__ uint8_t *quantScale2,
                                __gm__ uint8_t *quantOffset2,
                                __gm__ uint8_t *antiquantScale,
                                __gm__ uint8_t *antiquantOffset,
                                __gm__ uint8_t *blockTable,
                                __gm__ uint8_t *queryPaddingSize,
                                __gm__ uint8_t *kvPaddingSize,
                                __gm__ uint8_t *keyAntiquantScale,
                                __gm__ uint8_t *keyAntiquantOffset,
                                __gm__ uint8_t *valueAntiquantScale,
                                __gm__ uint8_t *valueAntiquantOffset,
                                __gm__ uint8_t *queryRope,
                                __gm__ uint8_t *keyRope,
                                __gm__ uint8_t *keyRopeAntiquantScale,
                                __gm__ uint8_t *attentionOut,
                                __gm__ uint8_t *softmaxLse);
    __aicore__ inline void InitQBuffer(uint32_t batchSize,
                                       uint32_t kvHeadNum,
                                       uint32_t gSize,
                                       uint32_t qSeqSize,
                                       uint32_t headDim,
                                       GlobalTensor<uint64_t> actualSeqLengthsGmQ,
                                       uint32_t actualLenQDims,
                                       FaGmTensor<Q_T, Q_FORMAT> &qGmTensor,
                                       GlobalTensor<Q_T> &qGm);
    __aicore__ inline void InitKVBuffer(uint32_t batchSize,
                                        uint32_t kvSeqSize,
                                        GlobalTensor<uint64_t> actualSeqLengthsGmQ,
                                        uint32_t actualLenDims,
                                        uint32_t kvHeadNum,
                                        uint32_t kvCacheBlockSize,
                                        uint32_t headDim,
                                        FaGmTensor<KV_T, KV_FORMAT> &kvGmTensor,
                                        GlobalTensor<KV_T> &kvGm,
                                        uint64_t *stride = nullptr);
    __aicore__ inline void InitMm1GlobalTensor(GlobalTensor<MM_OUT_T> mm1ResGm);
    __aicore__ inline void InitMm2GlobalTensor(GlobalTensor<KV_T> vec1ResGm, GlobalTensor<MM_OUT_T> mm2ResGm);

    __aicore__ inline void InitBuffers(TPipe *pipe);
    __aicore__ inline void AllocEventID();
    __aicore__ inline void FreeEventID();

    __aicore__ inline void ComputeMm1(const RunInfo &info);
    __aicore__ inline void ComputeMm2(const RunInfo &info);

  protected:
    template <typename T> __aicore__ inline T Align(T num, T rnd)
    {
        return (((rnd) == 0) ? 0 : (((num) + (rnd)-1) / (rnd) * (rnd)));
    }

    template <typename T> __aicore__ inline size_t BlockAlign(size_t s)
    {
        if constexpr (IsSameType<T, int4b_t>::value) {
            return (s + 63) / 64 * 64;
        }
        size_t n = (32 / sizeof(T));
        return (s + n - 1) / n * n;
    }

    __aicore__ inline void InitValueGm(uint32_t bIdx);
    __aicore__ inline void InitKeyGm(uint32_t bIdx);
    __aicore__ inline void UpdateKey(uint32_t bIdx);
    __aicore__ inline void UpdateValue(uint32_t bIdx);

    __aicore__ inline void CopyKeyToL1(const RunInfo &info,
                                       uint32_t kSize,
                                       uint32_t kStart,
                                       uint32_t kDealSize,
                                       uint32_t nSize,
                                       uint32_t nStart,
                                       uint32_t nDealSize,
                                       uint32_t nopeDealSize,
                                       uint32_t ropeDealSize,
                                       uint64_t l1Offset);

    __aicore__ inline void DealMm1SingleMKN(const RunInfo &info,
                                            uint32_t mSize,
                                            uint32_t mStart,
                                            uint32_t mDealSize,
                                            uint32_t kSize,
                                            uint32_t kStart,
                                            uint32_t kDealSize,
                                            uint32_t nSize,
                                            uint32_t nStart,
                                            uint32_t nDealSize,
                                            uint32_t nopeDealSize,
                                            uint32_t ropeDealSize);
    __aicore__ inline void DealMm2SingleMKN(const RunInfo &info,
                                            uint32_t mSize,
                                            uint32_t mStart,
                                            uint32_t mDealSize,
                                            uint32_t kSize,
                                            uint32_t kStart,
                                            uint32_t kDealSize,
                                            uint32_t nSize,
                                            uint32_t nStart,
                                            uint32_t nDealSize);
    __aicore__ inline void CopyQGmToL1(uint32_t nopeDealSize,
                                       uint32_t ropeDealSize,
                                       uint32_t mActSizeAlign,
                                       uint32_t bIdx,
                                       uint32_t n2Idx,
                                       uint32_t gS1Idx,
                                       uint32_t kStart,
                                       uint32_t mActSize);
    __aicore__ inline void CopyQDealSizeToL1(uint32_t DealSize,
                                             uint64_t queryL1Offset,
                                             uint32_t mActSizeAlign,
                                             uint32_t bIdx,
                                             uint32_t n2Idx,
                                             uint32_t gS1Idx,
                                             uint32_t dIdx,
                                             uint32_t mActSize,
                                             FaGmTensor<Q_T, Q_FORMAT> &qGmTensor);

  protected:
    // key和value的TensorList原始地址
    __gm__ uint8_t *keyPtr = nullptr;
    __gm__ uint8_t *valuePtr = nullptr;
    // mm1
    GlobalTensor<Q_T> queryGm;
    GlobalTensor<Q_T> qRopeGm;
    GlobalTensor<KV_T> keyGm;
    GlobalTensor<KV_T> keyRopeGm;
    GlobalTensor<MM_OUT_T> mm1ResGm;

    // mm2
    GlobalTensor<KV_T> vec1ResGm;
    GlobalTensor<KV_T> valueGm;
    GlobalTensor<MM_OUT_T> mm2ResGm;

    GlobalTensor<uint64_t> actualSeqLengthsGmQ;
    GlobalTensor<uint64_t> actualSeqLengthsGm;
    __gm__ uint8_t *actualSeqLengths = nullptr;

    // block_table
    GlobalTensor<int32_t> blockTableGm;

    ConstInfo constInfo{};

    // =================================L1 Buffer=================================
    static constexpr uint32_t L1_QP_SIZE = 128 * 1024;
    static constexpr uint32_t L1_KV_SIZE = 128 * 1024;
    // QP复用buffer,组成DB
    TBuf<TPosition::A1> qpBufL1;
    LocalTensor<Q_T> qpL1Tensor;
    // QP复用buffer,组成DB
    TBuf<TPosition::A1> kvBufL1;
    LocalTensor<KV_T> kvL1Tensor;

    // =================================L0 Buffer=================================
    // L0 buffer size
    static constexpr uint32_t L0A_PP_SIZE = 32 * 1024;
    static constexpr uint32_t L0B_PP_SIZE = 32 * 1024;
    static constexpr uint32_t L0C_PP_SIZE = 64 * 1024;
    // L0_A
    TBuf<TPosition::A2> tmpBufL0A;
    LocalTensor<KV_T> aL0TensorPingPong;
    // L0_B
    TBuf<TPosition::B2> tmpBufL0B;
    LocalTensor<KV_T> bL0TensorPingPong;
    // L0_C
    TBuf<TPosition::CO1> tmpBufL0C;
    LocalTensor<T> cL0TensorPingPong;

    // =================================Event&Buffer ID===========================
    // mte2 <> mte1 EventID
    static constexpr uint32_t QP_EVENT0 = EVENT_ID2;
    static constexpr uint32_t QP_EVENT1 = EVENT_ID3;
    uint32_t qpBufId = 0;
    static constexpr uint32_t KV_EVENT0 = EVENT_ID4;
    static constexpr uint32_t KV_EVENT1 = EVENT_ID5;
    uint32_t kvBufId = 0;
    // mte1 <> mmad EventID
    static constexpr uint32_t L0AB_EVENT0 = EVENT_ID3;
    static constexpr uint32_t L0AB_EVENT1 = EVENT_ID4;
    uint32_t l0abBufId = 0;
    // mmad <> fixpipe EventID
    static constexpr uint32_t L0C_EVENT0 = EVENT_ID3;
    static constexpr uint32_t L0C_EVENT1 = EVENT_ID4;
    uint32_t l0cBufId = 0;

    __gm__ uint8_t *actualSequenceLengthsQ = nullptr;

  private:
    FaGmTensor<Q_T, Q_FORMAT> queryGmTensor;
    FaGmTensor<Q_T, Q_FORMAT> queryRopeGmTensor;
    CopyQueryGmToL1<Q_T, Q_FORMAT> copyQueryGmToL1;

    FaGmTensor<KV_T, KV_FORMAT> keyGmTensor;
    FaGmTensor<KV_T, KV_FORMAT> keyRopeGmTensor;
    FaGmTensor<KV_T, KV_FORMAT> valueGmTensor;
    CopyKvGmToL1<KV_T, KV_FORMAT> copyKvGmToL1;
};

template <typename FIAT> __aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitKeyGm(uint32_t bIdx)
{
    ListTensorDesc keyListTensorDesc((__gm__ void *)keyPtr);
    __gm__ uint8_t *key_ = (__gm__ uint8_t *)keyListTensorDesc.GetDataPtr<__gm__ uint8_t>(bIdx);

    keyGm.SetGlobalBuffer((__gm__ KV_T *)key_);
    if (constInfo.l2CacheOffFlag) {
        // 关闭K、V的L2 Cache
#ifndef ASCENDC_OOM
        keyGm.SetL2CacheHint(CacheMode::CACHE_MODE_DISABLE);
#endif
    }
}

template <typename FIAT> __aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitValueGm(uint32_t bIdx)
{
    ListTensorDesc valueListTensorDesc((__gm__ void *)valuePtr);
    __gm__ uint8_t *value_ = (__gm__ uint8_t *)valueListTensorDesc.GetDataPtr<__gm__ uint8_t>(bIdx);

    valueGm.SetGlobalBuffer((__gm__ KV_T *)value_);
    if (constInfo.l2CacheOffFlag) {
        // 关闭K、V的L2 Cache
#ifndef ASCENDC_OOM
        valueGm.SetL2CacheHint(CacheMode::CACHE_MODE_DISABLE);
#endif
    }
}

template <typename FIAT> __aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitParams(const ConstInfo &constInfo)
{
    this->constInfo = constInfo;
}

template <typename FIAT>
__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::Init(__gm__ uint8_t *query,
                                                        __gm__ uint8_t *key,
                                                        __gm__ uint8_t *value,
                                                        __gm__ uint8_t *pseShift,
                                                        __gm__ uint8_t *attenMask,
                                                        __gm__ uint8_t *actualSeqLengthsQ,
                                                        __gm__ uint8_t *actualSeqLengths,
                                                        __gm__ uint8_t *deqScale1,
                                                        __gm__ uint8_t *quantScale1,
                                                        __gm__ uint8_t *deqScale2,
                                                        __gm__ uint8_t *quantScale2,
                                                        __gm__ uint8_t *quantOffset2,
                                                        __gm__ uint8_t *antiquantScale,
                                                        __gm__ uint8_t *antiquantOffset,
                                                        __gm__ uint8_t *blockTable,
                                                        __gm__ uint8_t *queryPaddingSize,
                                                        __gm__ uint8_t *kvPaddingSize,
                                                        __gm__ uint8_t *keyAntiquantScale,
                                                        __gm__ uint8_t *keyAntiquantOffset,
                                                        __gm__ uint8_t *valueAntiquantScale,
                                                        __gm__ uint8_t *valueAntiquantOffset,
                                                        __gm__ uint8_t *queryRope,
                                                        __gm__ uint8_t *keyRope,
                                                        __gm__ uint8_t *keyRopeAntiquantScale,
                                                        __gm__ uint8_t *attentionOut,
                                                        __gm__ uint8_t *softmaxLse)
{
    uint32_t qkTensorD = constInfo.ropeSplitMode ? constInfo.headDim : (constInfo.headDim + constInfo.headDimRope);

    // init global buffer
    queryGm.SetGlobalBuffer((__gm__ Q_T *)query);
    InitQBuffer(constInfo.batchSize,
                constInfo.kvHeadNum,
                constInfo.gSize,
                constInfo.qSeqSize,
                qkTensorD,
                actualSeqLengthsGmQ,
                constInfo.actualLenQDims,
                queryGmTensor,
                queryGm);

    if (constInfo.ropeSplitMode) {
        // query rope
        qRopeGm.SetGlobalBuffer((__gm__ Q_T *)queryRope);
        InitQBuffer(constInfo.batchSize,
                    constInfo.kvHeadNum,
                    constInfo.gSize,
                    constInfo.qSeqSize,
                    constInfo.headDimRope,
                    actualSeqLengthsGmQ,
                    constInfo.actualLenQDims,
                    queryRopeGmTensor,
                    qRopeGm);
        // key rope
        keyRopeGm.SetGlobalBuffer((__gm__ KV_T *)keyRope);
        InitKVBuffer(constInfo.batchSize,
                     constInfo.kvSeqSize,
                     actualSeqLengthsGm,
                     constInfo.actualLenDims,
                     constInfo.kvHeadNum,
                     constInfo.kvCacheBlockSize,
                     constInfo.headDimRope,
                     keyRopeGmTensor,
                     keyRopeGm,
                     constInfo.keyRopeStride);
    }

    keyPtr = key;
    valuePtr = value;
    // batch连续时,只需要初始化一次;不连续时,需要在使用时根据batchIdx初始化
    if (constInfo.batchContinuous) {
        InitKeyGm(0);
        InitKVBuffer(constInfo.batchSize,
                     constInfo.kvSeqSize,
                     actualSeqLengthsGm,
                     constInfo.actualLenDims,
                     constInfo.kvHeadNum,
                     constInfo.kvCacheBlockSize,
                     qkTensorD,
                     keyGmTensor,
                     keyGm,
                     constInfo.keyStride);

        InitValueGm(0);
        InitKVBuffer(constInfo.batchSize,
                     constInfo.kvSeqSize,
                     actualSeqLengthsGm,
                     constInfo.actualLenDims,
                     constInfo.kvHeadNum,
                     constInfo.kvCacheBlockSize,
                     constInfo.headDim,
                     valueGmTensor,
                     valueGm,
                     constInfo.valueStride);
    }

    if (constInfo.actualLenQDims != 0) {
        actualSeqLengthsGmQ.SetGlobalBuffer((__gm__ uint64_t *)actualSeqLengthsQ, constInfo.actualLenQDims);
        this->actualSequenceLengthsQ = actualSeqLengthsQ;
    }
    if (constInfo.actualLenDims != 0) {
        actualSeqLengthsGm.SetGlobalBuffer((__gm__ uint64_t *)actualSeqLengths, constInfo.actualLenDims);
        this->actualSeqLengths = actualSeqLengths;
    }
    if constexpr (PAGE_ATTENTION) {
        blockTableGm.SetGlobalBuffer((__gm__ int32_t *)blockTable);
    }
}

template <typename FIAT>
__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitQBuffer(uint32_t batchSize,
                                                               uint32_t kvHeadNum,
                                                               uint32_t gSize,
                                                               uint32_t qSeqSize,
                                                               uint32_t headDim,
                                                               GlobalTensor<uint64_t> actualSeqLengthsGmQ,
                                                               uint32_t actualLenQDims,
                                                               FaGmTensor<Q_T, Q_FORMAT> &qGmTensor,
                                                               GlobalTensor<Q_T> &qGm)
{
    qGmTensor.gmTensor = qGm;
    if constexpr (GmLayoutParams<Q_FORMAT>::CATEGORY == FormatCategory::GM_Q_OUT_BNGSD) {
        qGmTensor.offsetCalculator.Init(
            batchSize, kvHeadNum, gSize, qSeqSize, headDim, actualSeqLengthsGmQ, actualLenQDims);
    } else if constexpr (GmLayoutParams<Q_FORMAT>::CATEGORY == FormatCategory::GM_Q_OUT_TND) {
        qGmTensor.offsetCalculator.Init(kvHeadNum, gSize, headDim, actualSeqLengthsGmQ, actualLenQDims);
    }
}

template <typename FIAT>
__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitKVBuffer(uint32_t batchSize,
                                                                uint32_t kvSeqSize,
                                                                GlobalTensor<uint64_t> actualSeqLengthsGmQ,
                                                                uint32_t actualLenDims,
                                                                uint32_t kvHeadNum,
                                                                uint32_t kvCacheBlockSize,
                                                                uint32_t headDim,
                                                                FaGmTensor<KV_T, KV_FORMAT> &kvGmTensor,
                                                                GlobalTensor<KV_T> &kvGm,
                                                                uint64_t *stride)
{
    kvGmTensor.gmTensor = kvGm;
    if constexpr (PAGE_ATTENTION) {
        if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_PA_BNBD) {
            kvGmTensor.offsetCalculator.Init(
                kvHeadNum, kvCacheBlockSize, headDim, blockTableGm, constInfo.maxBlockNumPerBatch, stride);
        } else if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_PA_NZ) {
            uint32_t d0 = 32 / sizeof(KV_T);
            uint32_t d1 = headDim / d0;
            kvGmTensor.offsetCalculator.Init(
                kvHeadNum, kvCacheBlockSize, d1, d0, blockTableGm, constInfo.maxBlockNumPerBatch, stride);
        }
    } else {
        if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_BNSD) {
            kvGmTensor.offsetCalculator.Init(batchSize, kvHeadNum, kvSeqSize, headDim);
        } else if constexpr (GmLayoutParams<KV_FORMAT>::CATEGORY == FormatCategory::GM_KV_TND) {
            kvGmTensor.offsetCalculator.Init(kvHeadNum, headDim, actualSeqLengthsGm, actualLenDims);
        }
    }
}

template <typename FIAT>
__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitMm1GlobalTensor(GlobalTensor<MM_OUT_T> mm1ResGm)
{
    // mm1
    this->mm1ResGm = mm1ResGm;
}

template <typename FIAT>
__aicore__ inline void FiaBlockCubeNonQuant<FIAT>::InitMm2GlobalTensor(GlobalTensor<KV_T> vec1ResGm,
                                                                       GlobalTensor<MM_OUT_T> mm2ResGm)
{
