11	// ========================================================================
12	// mhc_sandwich_norm_post_preonly_kernel_io.h
13	// IO building blocks: 双核同步、workspace 读写、输出写入
14	// ========================================================================
15	
16	// ---- Dual-core synchronization ----
17	
18	/// Write my scalars to workspace (own data slot).
19	/// Caller must follow with SyncAndReadPartner to exchange.
20	__aicore__ inline void DualCoreSyncExchange(
21	    float mySumSqPre, const float (&myXHat)[N_MAX],
22	    float &totalSumSqPre, float (&xHatVals)[N_MAX])
23	{
24	    uint32_t mySync1Slot   = (coreRole_ == 0) ? WS_SYNC1_CORE0 : WS_SYNC1_CORE1;
25	    uint32_t partSync1Slot = (coreRole_ == 0) ? WS_SYNC1_CORE1 : WS_SYNC1_CORE0;
26	    uint32_t myBlockIdx      = GetBlockIdx();
27	    uint32_t partnerBlockIdx = (coreRole_ == 0) ? (myBlockIdx + 1) : (myBlockIdx - 1);
28	
29	    LocalTensor<float> scBuf = bufScalar_.Get<float>();
30	
31	    // Pack sync1 block
32	    scBuf.SetValue(0, mySumSqPre);
33	    for (uint32_t o = 0; o < phiRows_; ++o)
34	        scBuf.SetValue(1 + o, myXHat[o]);
35	    for (uint32_t i = 1 + phiRows_; i < WS_SYNC_BLOCK; ++i)
36	        scBuf.SetValue(i, 0.0f);
37	    PipeBarrier<PIPE_V>();
38	
39	    // Write scalars
40	    DataCopyExtParams wp = {1, 0, 0, 0, 0};
41	    wp.blockLen = WS_SYNC_BLOCK * sizeof(float);
42	    DataCopyPad(workspaceGm_[pairWsBase_ + mySync1Slot], scBuf, wp);
43	}
44	
45	/// Write x2 from UB to workspace GM (for partner to read)
46	__aicore__ inline void WriteX2ToWorkspace(uint32_t tD, uint32_t tOff,
47	    LocalTensor<float> x2Src, uint32_t numHeads, uint32_t wsSlot)
48	{
49	    for (uint32_t hi = 0; hi < numHeads; ++hi) {
50	        DataCopyExtParams wp = {1, 0, 0, 0, 0};
51	        wp.blockLen = tD * sizeof(float);
52	        DataCopyPad(workspaceGm_[pairWsBase_ + wsSlot + (uint64_t)hi * D_ + tOff],
53	                    x2Src[hi * dimTile_], wp);
54	    }
55	}
56	
57	// ---- Sense-reversing barrier (write-own-only) ----
58	// Replaces IBSet/IBWait to eliminate cross-core GM writes (mssanitizer OOB).
59	// Each core only writes to its own flag; reads partner's flag via spin.
60	// Polarity flips each round (0→1→0→...) so no reset/clear phase is needed.
61	
62	/// Sense-reversing barrier: signal own readiness + wait for partner.
63	/// Each core writes ONLY to syncGm_[ownBlockIdx], reads partner's slot.
64	__aicore__ inline void SyncBarrier(uint32_t partnerBlockIdx)
65	{
66	    int32_t syncVal = (syncRound_ & 1) ? 0 : 1;
67	    uint32_t mySlot   = GetBlockIdx() * WS_SYNC_BLOCK;
68	    uint32_t partSlot = partnerBlockIdx * WS_SYNC_BLOCK;
69	
70	    // Signal: write syncVal to own slot
71	    LocalTensor<int32_t> syncUb = bufSyncUb_.AllocTensor<int32_t>();
72	    syncUb.SetValue(0, syncVal);
73	    for (uint32_t i = 1; i < WS_SYNC_BLOCK; ++i) syncUb.SetValue(i, 0);
74	    PipeBarrier<PIPE_V>();
75	    DataCopy(syncGm_[mySlot], syncUb, WS_SYNC_BLOCK);
76	    PipeBarrier<PIPE_ALL>();
77	    bufSyncUb_.FreeTensor(syncUb);
78	
79	    // Wait: spin-read partner's slot until syncVal
80	    syncUb = bufSyncUb_.AllocTensor<int32_t>();
81	    // 一个手写Barrier，用来在处理一个token的两个核之间做同步：
82	    // 1. 每个核把 syncVal 写进GM上自己的slot；
83	    // 2.while循环不停地从GM读对方核的slot到UB，直到它等于本轮的syncVal；
84	    // 3. 一旦读到对方的值，说明对方达到屏障点，跳出，双核对齐。
85	    while (true) {
86	        DataCopy(syncUb, syncGm_[partSlot], WS_SYNC_BLOCK);
87	        PipeBarrier<PIPE_ALL>();
88	        if (syncUb.GetValue(0) == syncVal) {
89	            break;
90	        }
91	    }
92	    bufSyncUb_.FreeTensor(syncUb);
93	
94	    syncRound_++;
95	}
96	
97	/// Sync + read partner's sync block, combine partials.
98	__aicore__ inline void SyncAndReadPartner(
99	    float mySumSqPre, const float (&myXHat)[N_MAX],
100	    float &totalSumSqPre, float (&xHatVals)[N_MAX])
101	{
102	    uint32_t partnerBlockIdx = (coreRole_ == 0) ? (GetBlockIdx() + 1) : (GetBlockIdx() - 1);
103	    uint32_t partSync1Slot   = (coreRole_ == 0) ? WS_SYNC1_CORE1 : WS_SYNC1_CORE0;
104	
105	    PipeBarrier<PIPE_ALL>();
106	    SyncBarrier(partnerBlockIdx);
107	
108	    // Read partner's sync1 block
109	    LocalTensor<float> scBuf = bufScalar_.Get<float>();
110	    DataCopyExtParams rp = {1, 0, 0, 0, 0};
111	    rp.blockLen = WS_SYNC_BLOCK * sizeof(float);
112	    DataCopyPadExtParams<float> rpad = {false, 0, 0, 0};
113	    DataCopyPad(scBuf, workspaceGm_[pairWsBase_ + partSync1Slot], rp, rpad);
114	    PipeBarrier<PIPE_ALL>();
115	
116	    totalSumSqPre = mySumSqPre + scBuf.GetValue(0);
117	    for (uint32_t o = 0; o < phiRows_; ++o)
118	        xHatVals[o] = myXHat[o] + scBuf.GetValue(1 + o);
119	}
120	
121	
122	/// In-place quantize round-trip: fp32 → io_dtype → fp32
123	/// Simulates stage-boundary dtype truncation to match golden
124	__aicore__ inline void QuantizeRoundTrip(LocalTensor<float> buf, uint32_t count)
125	{
126	    LocalTensor<T> tmp = bufHInPrimeBf16_.AllocTensor<T>();
127	    CastToIO(tmp, buf, count);
128	    PipeBarrier<PIPE_V>();  // RAW on tmp: CastToIO must finish writing before Cast reads
129	    Cast(buf, tmp, RoundMode::CAST_NONE, count);
130	    PipeBarrier<PIPE_V>();
131	    bufHInPrimeBf16_.FreeTensor(tmp);
132	}
133	
134	/// Read partner's x2[hi] for one tile from workspace into dst buffer
135	__aicore__ inline void ReadPartnerX2Tile(LocalTensor<float> dst,
136	    uint32_t hi, uint32_t tOff, uint32_t tD)
137	{
138	    uint32_t partnerX2WsSlot = WS_HIN_BASE + (1 - coreRole_) * myHeadCount_ * D_;
139	    DataCopyExtParams rp = {1, 0, 0, 0, 0};
140	    rp.blockLen = tD * sizeof(float);
141	    DataCopyPadExtParams<float> rpad = {false, 0, 0, 0};
142	    DataCopyPad(dst, workspaceGm_[pairWsBase_ + partnerX2WsSlot +
143	                (uint64_t)hi * D_ + tOff], rp, rpad);
144	    PipeBarrier<PIPE_ALL>();
145	}
146	
147	// ---- Output helpers ----
148	
149	/// Cast fp32 → T with correct RoundMode
150	__aicore__ inline void CastToIO(LocalTensor<T> dst, LocalTensor<float> src,
151	    uint32_t count)
152	{
153	    if constexpr (IsSameT<T, half>::value)
154	        Cast(dst, src, RoundMode::CAST_NONE, count);
155	    else
156	        Cast(dst, src, RoundMode::CAST_RINT, count);
157	}
158	
159	/// Cast + write one tile of h_in_prime to GM
160	__aicore__ inline void WriteHInPrimeTile(LocalTensor<float> src,
161	    uint64_t gmOffset, uint32_t tD)
162	{
163	    LocalTensor<T> hIpBf16 = bufHInPrimeBf16_.AllocTensor<T>();
164	    CastToIO(hIpBf16, src, tD);
165	    bufHInPrimeBf16_.EnQue(hIpBf16);
166	    hIpBf16 = bufHInPrimeBf16_.DeQue<T>();
167	    DataCopy(hInPrimeGm_[gmOffset], hIpBf16, tD);
168	    bufHInPrimeBf16_.FreeTensor(hIpBf16);
169	
170	    // src(32) copyout hInF32
171	    if (returnHInF32_) {
172	        // tbuf分配的local tensor可以做搬入搬出，但要手动加同步
173	        SetFlag<HardEvent::V_MTE3>(evtVtoMte3_);
174	        WaitFlag<HardEvent::V_MTE3>(evtVtoMte3_);
175	
176	        DataCopy(hInF32Gm_[gmOffset], src, tD);
177	
178	        SetFlag<HardEvent::MTE3_V>(evtMte3toV_);
179	        WaitFlag<HardEvent::MTE3_V>(evtMte3toV_);
180	    }
181	}
182	
183	/// Cast + write one head's x2_out tile to GM
184	__aicore__ inline void WriteX2OutTile(LocalTensor<float> src,
185	    uint64_t gmOffset, uint32_t tD)
186	{
187	    LocalTensor<T> x2Bf16 = bufHInPrimeBf16_.AllocTensor<T>();
188	    CastToIO(x2Bf16, src, tD);
189	    bufHInPrimeBf16_.EnQue(x2Bf16);
190	    x2Bf16 = bufHInPrimeBf16_.DeQue<T>();
191	    DataCopy(x2OutGm_[gmOffset], x2Bf16, tD);
192	    bufHInPrimeBf16_.FreeTensor(x2Bf16);
193	}
194	
195	// ---- Misc ----
196	
197	/// Get x2[head hi, tile t] from the appropriate UB buffer (multi-tile dual-core)
198	///   tile 0: head0 → bufGamma1Fp32_, head1 → bufGamma2Fp32_
199	///   tile 1: head0..1 → bufX2Fp32_
200	__aicore__ inline __attribute__((always_inline)) LocalTensor<float>
201	GetX2HeadTile(uint32_t tile, uint32_t hi)
202	{
203	    if (tile == 0) {
204	        return (hi == 0) ? bufGamma1Fp32_.Get<float>()
205	                         : bufGamma2Fp32_.Get<float>();
206	    }
207	    return bufX2Fp32_.Get<float>()[hi * dimTile_];
208	}
209	
210	__aicore__ inline uint32_t GetTileD(uint32_t tile) const
211	{
212	    if (lastDimTile_ != 0 && tile == dimLoop_ - 1) return lastDimTile_;
213	    return dimTile_;
214	}
