216	// sum of ||x2[h]||^2 across N heads (single-core path)
217	__aicore__ inline float ComputeSumSqAllHeads(uint32_t tD);
218	// phi matmul for one tile (single-core path)
219	__aicore__ inline void ComputePhiMatmulTile(uint32_t tD, uint32_t tOff,
220	    float (&xHatVals)[N_MAX]);
221	// N*D global RMSNorm_mid (single-core single-tile)
222	__aicore__ inline void ApplyRmsNormMidSingleTile(uint32_t tD);
