286	    constInfo.headDimRope = tilingData->baseParams.headDimRope;
287	    constInfo.headDimAlign = Align(constInfo.headDim, (uint64_t)fa_base_vector::BYTE_BLOCK);
288	
289	    constInfo.mmResUbSize = tilingData->workspaceParams.mm1ResSize;
290	    constInfo.bmm2ResUbSize = tilingData->workspaceParams.mm2ResSize;
291	    constInfo.vec1ResUbSize = constInfo.mmResUbSize;
292	
293	    constInfo.preLoadNum = PRELOAD_NUM;
294	    constInfo.nBufferMBaseSize = N_BUFFER_M_BASIC_SIZE;
295	    constInfo.syncV0C1 = SYNC_V0_C1_FLAG;
296	    constInfo.syncC1V1 = SYNC_C1_V1_FLAG;
297	    constInfo.syncV1C2 = SYNC_V1_C2_FLAG;
298	    constInfo.syncC2V2 = SYNC_C2_V2_FLAG;
299	    constInfo.syncC2V1 = SYNC_C2_V1_FLAG;
300	    constInfo.syncV2C2 = SYNC_V2_C2_FLAG;
301	    constInfo.syncV1NupdateC2 = SYNC_V1_NUPDATE_C2_FLAG;
302	// 读取非连续 stride
303	#ifdef ASCENDC_CPU_DEBUG
304	    const uint64_t *keyStridePtr = tilingData->pageAttenParams.keyStride;
305	    const uint64_t *valueStridePtr = tilingData->pageAttenParams.valueStride;
306	    const uint64_t *keyRopeStridePtr = tilingData->pageAttenParams.keyRopeStride;
307	#else
308	    uint64_t keyStridePtr[ARRAY_SIZE(tilingData->pageAttenParams.keyStride)];
309	    uint64_t valueStridePtr[ARRAY_SIZE(tilingData->pageAttenParams.valueStride)];
310	    uint64_t keyRopeStridePtr[ARRAY_SIZE(tilingData->pageAttenParams.keyRopeStride)];
311	    copy_data_align64(
312	        (uint8_t *)keyStridePtr, (uint8_t *)(tilingData->pageAttenParams.keyStride), sizeof(keyStridePtr));
313	    copy_data_align64(
314	        (uint8_t *)valueStridePtr, (uint8_t *)(tilingData->pageAttenParams.valueStride), sizeof(valueStridePtr));
315	    copy_data_align64(
316	        (uint8_t *)keyRopeStridePtr, (uint8_t *)(tilingData->pageAttenParams.keyRopeStride), sizeof(keyRopeStridePtr));
317	#endif
318	    if (keyStridePtr[0] > 0) {
319	        for (uint32_t i = 0; i < 5; i++) {
320	            constInfo.keyStride[i] = keyStridePtr[i];
321	            constInfo.valueStride[i] = valueStridePtr[i];
322	            constInfo.keyRopeStride[i] = keyRopeStridePtr[i];
323	        }
324	    }
