339	template <typename FIAT> __aicore__ inline void FiaKernelNonQuant<FIAT>::InitOutputSingleCore()
340	{
341	    if (usedCoreNum != 0) {
342	        uint32_t initOutputEventId = 0U;
343	        SetFlag<AscendC::HardEvent::MTE3_V>(initOutputEventId);
344	        uint64_t tSize = constInfo.batchSize * constInfo.qSeqSize;
345	        if constexpr (LAYOUT_T == FIA_LAYOUT::TND || LAYOUT_T == FIA_LAYOUT::NTD) {
346	            tSize = constInfo.qTSize;
347	        }
348	        // TND、NTD场景,S1和actualSeq相等,不需要初始化
349	        if (IsInitAttentionOutGm()) {
350	            uint64_t totalOutputSize = tSize * constInfo.qHeadNum * constInfo.headDim;
351	            uint64_t singleCoreSize =
352	                (totalOutputSize + (2 * usedCoreNum) - 1) / (2 * usedCoreNum); // 2 means c:v = 1:2
353	            uint64_t tailSize = totalOutputSize - tmpBlockIdx * singleCoreSize;
354	            uint64_t singleInitOutputSize = tailSize < singleCoreSize ? tailSize : singleCoreSize;
355	            WaitFlag<AscendC::HardEvent::MTE3_V>(initOutputEventId);
356	            if (tmpBlockIdx * singleCoreSize < totalOutputSize && singleInitOutputSize > 0) {
357	                matmul::InitOutput<OUT_T>(attentionOutGm[tmpBlockIdx * singleCoreSize], singleInitOutputSize, 0);
358	            }
359	            SetFlag<AscendC::HardEvent::MTE3_V>(initOutputEventId);
360	        }
361	
362	        if (constInfo.softmaxLseFlag) {
363	            float lseInitValue = constInfo.FLOAT_INF;
364	            uint64_t totalLseSize = tSize * constInfo.qHeadNum;
365	            uint64_t singleCoreLseSize =
366	                (totalLseSize + (2 * usedCoreNum) - 1) / (2 * usedCoreNum); // 2 means c:v = 1:2;
367	            uint64_t tailLseSize = totalLseSize - tmpBlockIdx * singleCoreLseSize;
368	            uint64_t singleInitOutputLseSize = tailLseSize < singleCoreLseSize ? tailLseSize : singleCoreLseSize;
369	            WaitFlag<AscendC::HardEvent::MTE3_V>(initOutputEventId);
370	            if (tmpBlockIdx * singleCoreLseSize < totalLseSize && singleInitOutputLseSize > 0) {
371	                matmul::InitOutput<float>(
372	                    softmaxLseGm[tmpBlockIdx * singleCoreLseSize], singleInitOutputLseSize, lseInitValue);
373	            }
374	            SetFlag<AscendC::HardEvent::MTE3_V>(initOutputEventId);
375	        }
376	        WaitFlag<AscendC::HardEvent::MTE3_V>(initOutputEventId);
377	        SyncAll();
378	    }
379	}
