404	template <typename FIAT> __aicore__ inline void FiaKernelNonQuant<FIAT>::InitWorkspace(__gm__ uint8_t *workspace)
405	{
406	    // workspace 内存排布
407	    // |Q--|mm1ResGm(存S)|vec1ResGm(存A1,A2)|mm2ResGm(存O)|vec2ResGm
408	    // |Core0_Q1-Core0_Q2-Core1_Q1-Core1_Q2....Core32_Q1-Core32_Q2|Core0_mmRes
409	    static constexpr uint32_t dbWorkspaceRatio = PRELOAD_NUM;
410	    uint64_t offset = 0;
411	    // mm1Res
412	    mm1ResGm.SetGlobalBuffer(
413	        (__gm__ MM1_OUT_T *)(workspace + offset +
414	                             aiCoreIdx * dbWorkspaceRatio * constInfo.mmResUbSize * sizeof(MM1_OUT_T)));
415	    offset += GetBlockNum() * dbWorkspaceRatio * constInfo.mmResUbSize * sizeof(MM1_OUT_T);
416	
417	    // vec1Res
418	    vec1ResGm.SetGlobalBuffer(
419	        (__gm__ KV_T *)(workspace + offset + aiCoreIdx * dbWorkspaceRatio * constInfo.mmResUbSize * sizeof(KV_T)));
420	    offset += GetBlockNum() * dbWorkspaceRatio * constInfo.mmResUbSize * sizeof(KV_T);
421	
422	    // mm2Res
423	    mm2ResGm.SetGlobalBuffer(
424	        (__gm__ MM2_OUT_T *)(workspace + offset +
425	                             aiCoreIdx * dbWorkspaceRatio * constInfo.bmm2ResUbSize * sizeof(MM2_OUT_T)));
426	    offset += GetBlockNum() * dbWorkspaceRatio * constInfo.bmm2ResUbSize * sizeof(MM2_OUT_T);
427	
428	    // vec2Res
429	    vec2ResGm.SetGlobalBuffer(
430	        (__gm__ UPDATE_T *)(workspace + offset +
431	                            aiCoreIdx * dbWorkspaceRatio * constInfo.bmm2ResUbSize * sizeof(UPDATE_T)));
432	    offset += GetBlockNum() * dbWorkspaceRatio * constInfo.bmm2ResUbSize * sizeof(UPDATE_T);
433	
434	    // flash decode input
435	    if constexpr (FLASH_DECODE) {
436	        if (unlikely(fdFlag)) {
437	            accumOutGm.SetGlobalBuffer((__gm__ float *)(workspace + offset));
438	            offset = offset + tilingData->workspaceParams.fdAccumOutSize * sizeof(float);
439	            lseSumFdGm.SetGlobalBuffer((__gm__ float *)(workspace + offset));
440	            lseMaxFdGm.SetGlobalBuffer((__gm__ float *)(workspace + offset) +
441	                                       tilingData->workspaceParams.fdLogSumExpSize / 2);
442	            offset = offset + tilingData->workspaceParams.fdLogSumExpSize * sizeof(float);
443	        }
444	    }
445	}
