598	template <typename FIAT> __aicore__ inline void FiaKernelNonQuant<FIAT>::InitCalcParamsEach()
599	{
600	    // 这里是编译器优化写法，定义一个局部数组变量coreSidxEnd(存在栈上)，使用copy_data_align64接口
601	    // 可以只从ub中拷贝tiling中coreSidxEnd的内容到栈上，而非将整个increFlashAttentionCoreParams
602	    // 内容拷贝到栈，减少拷贝时间。
603	
604	    // 任务起始位置
605	    if (aiCoreIdx == 0) {
606	        constInfo.bN2Start = 0;
607	        constInfo.gS1Start = 0;
608	        constInfo.s2Start = 0;
609	    } else {
610	        constInfo.bN2Start =
611	            metadataGm.GetValue(optiling::GetAICMetaAbsIndex(aiCoreIdx - 1, optiling::BN2_END_PTR_INDEX));
612	        constInfo.gS1Start =
613	            metadataGm.GetValue(optiling::GetAICMetaAbsIndex(aiCoreIdx - 1, optiling::GS1_END_PTR_INDEX));
614	        constInfo.s2Start = metadataGm.GetValue(optiling::GetAICMetaAbsIndex(aiCoreIdx - 1, optiling::S2_END_PTR));
615	    }
616	    // 任务结束位置
617	    constInfo.bN2End = metadataGm.GetValue(optiling::GetAICMetaAbsIndex(aiCoreIdx, optiling::BN2_END_PTR_INDEX));
618	    constInfo.gS1End = metadataGm.GetValue(optiling::GetAICMetaAbsIndex(aiCoreIdx, optiling::GS1_END_PTR_INDEX));
619	    constInfo.s2End = metadataGm.GetValue(optiling::GetAICMetaAbsIndex(aiCoreIdx, optiling::S2_END_PTR));
620	
621	    // 首个S1G块、最后一个S1G块的S2是否被切分，在sparse模式下，需要和mask之后的起止点对比才能确定
622	    constInfo.headS2Split = false;
623	    constInfo.tailS2Split = false;
624	
625	    constInfo.coreStartKVSplitPos =
626	        metadataGm.GetValue(optiling::GetAICMetaAbsIndex(aiCoreIdx, optiling::S2_SPLIT_START_IDX_OF_CORE_INDEX));
627	    constInfo.isSkipSmallBlock = (constInfo.keySinkNumber && constInfo.sparseMode == fa_base_vector::BAND &&
628	                                  actualSeqLengthsGmQ.GetValue(constInfo.actualLenQDims - 1) < 32 * 1024 &&
629	                                  (constInfo.preToken + constInfo.nextToken) < 512);
630	}
