632	template <typename FIAT> __aicore__ inline void FiaKernelNonQuant<FIAT>::CalcAccumOffset(RunInfo &info)
633	{
634	    if ASCEND_IS_AIV {
635	        uint32_t bN2IdxOfFdHead_local[optiling::FIA_MAX_AIC_CORE_NUM] = {0};
636	        uint32_t gS1IdxOfFdHead_local[optiling::FIA_MAX_AIC_CORE_NUM] = {0};
637	        uint32_t s2SplitNumOfFdHead_local[optiling::FIA_MAX_AIC_CORE_NUM] = {0};
638	
639	        for (uint32_t i = 0; i < usedCoreNum; ++i) {
640	            bN2IdxOfFdHead_local[i] =
641	                metadataGm.GetValue(optiling::GetAICMetaAbsIndex(i, optiling::BN2_IDX_OF_FD_HEAD_INDEX));
642	            gS1IdxOfFdHead_local[i] =
643	                metadataGm.GetValue(optiling::GetAICMetaAbsIndex(i, optiling::GS1_IDX_OF_FD_HEAD_INDEX));
644	            s2SplitNumOfFdHead_local[i] =
645	                metadataGm.GetValue(optiling::GetAICMetaAbsIndex(i, optiling::S2_SPLIT_NUM_OF_FD_HEAD_INDEX));
646	        }
647	
648	        uint64_t accumTmpOutNum = 0;
649	        uint32_t taskId = 0;
650	        uint32_t curbN2Idx = info.bIdx * constInfo.kvHeadNum + info.n2Idx;
651	
652	        while (taskId < usedCoreNum) {
653	            if (bN2IdxOfFdHead_local[taskId] == curbN2Idx &&
654	                gS1IdxOfFdHead_local[taskId] * constInfo.mBaseSize == info.gS1Idx) {
655	                break;
656	            }
657	            accumTmpOutNum += s2SplitNumOfFdHead_local[taskId];
658	            taskId++;
659	        }
660	        info.accumTmpOutNum = accumTmpOutNum;
661	    }
662	}
