664	template <typename FIAT>
665	__aicore__ inline void FiaKernelNonQuant<FIAT>::GetSafeActToken(int64_t actSeqLensQ,
666	                                                                int64_t actSeqLensKv,
667	                                                                int64_t &safePreToken,
668	                                                                int64_t &safeNextToken)
669	{
670	    if (constInfo.sparseMode == fa_base_vector::DEFAULT_MASK) {
671	        safePreToken = Max(-actSeqLensKv, safePreToken);
672	        safePreToken = Min(safePreToken, actSeqLensQ);
673	        safeNextToken = Max(-actSeqLensQ, safeNextToken);
674	        safeNextToken = Min(safeNextToken, actSeqLensKv);
675	    } else if (constInfo.sparseMode == fa_base_vector::BAND) {
676	        safePreToken = Max(-actSeqLensQ, safePreToken);
677	        safePreToken = Min(safePreToken, actSeqLensKv);
678	        safeNextToken = Max(-actSeqLensKv, safeNextToken);
679	        safeNextToken = Min(safeNextToken, actSeqLensQ);
680	    }
681	}
682	template <typename FIAT>
683	__aicore__ inline void
684	FiaKernelNonQuant<FIAT>::CalcParams(uint64_t loop, uint32_t bN2Cur, uint32_t gS1Cur, uint32_t s2Cur, RunInfo &info)
685	{
686	    info.loop = loop;
687	
688	    info.bIdx = GetBIdx(bN2Cur);
689	    info.n2Idx = GetN2Idx(bN2Cur);
690	    info.gS1Idx = gS1Cur * constInfo.mBaseSize;
691	    info.s2Idx = s2Cur;
692	
693	    info.actS1Size = actSeqLensQ;
694	    info.actS2Size = actSeqLensKv;
695	
696	    info.actMBaseSize = constInfo.mBaseSize;
697	    uint64_t gS1Size = info.actS1Size * constInfo.gSize;
698	    if (((gS1Cur + 1) * constInfo.mBaseSize) > gS1Size) {
699	        info.actMBaseSize = gS1Size - gS1Cur * constInfo.mBaseSize;
700	    }
701	    info.actualSingleProcessSInnerSize = constInfo.s2BaseSize;
702	    if (((s2Cur + 1) * constInfo.s2BaseSize) > info.actS2Size) {
703	        info.actualSingleProcessSInnerSize = info.actS2Size - s2Cur * constInfo.s2BaseSize;
704	    }
705	    info.actualSingleProcessSInnerSize =
706	        info.isSinkTensor ? constInfo.keySinkNumber : info.actualSingleProcessSInnerSize;
707	
708	    info.actualSingleProcessSInnerSizeAlign =
709	        Align((uint32_t)info.actualSingleProcessSInnerSize, (uint32_t)fa_base_vector::BYTE_BLOCK);
710	
711	    if (constInfo.batchContinuous) {
712	        info.isChangeBatch = false;
713	    } else {
714	        if (loop == 0) { // 第一个有效任务才需要重置KV的tensor
715	            info.isChangeBatch = true;
716	        } else {
717	            info.isChangeBatch = (info.n2Idx == 0 && s2Cur == curS2Start);
718	        }
719	    }
720	
721	    int64_t preTokenLeftUp = 0;
722	    int64_t nextTokenLeftUp = 0;
723	    GetPreNextTokenLeftUp(actSeqLensQ, actSeqLensKv, preTokenLeftUp, nextTokenLeftUp);
724	    info.preTokenLeftUp = preTokenLeftUp;
725	    info.nextTokenLeftUp = nextTokenLeftUp;
726	
727	    int64_t safePreToken = constInfo.preToken;
728	    int64_t safeNextToken = constInfo.nextToken;
729	    GetSafeActToken(info.actS1Size, info.actS2Size, safePreToken, safeNextToken);
730	    if (constInfo.sparseMode == fa_base_vector::BAND) {
731	        info.preTokensPerBatch = safePreToken;
732	        info.nextTokensPerBatch =
733	            static_cast<int32_t>(info.actS2Size) - static_cast<int32_t>(info.actS1Size) + safeNextToken;
734	        if (constInfo.sinkNumber > 0) {
735	            info.nextTokensPerBatch = static_cast<int32_t>(info.actS2Size) -
736	                                      static_cast<int32_t>(constInfo.sinkNumber) -
737	                                      static_cast<int32_t>(info.actS1Size) + static_cast<int32_t>(safeNextToken);
738	        }
739	    } else if ((constInfo.sparseMode == fa_base_vector::DEFAULT_MASK) && constInfo.attenMaskFlag) {
740	        info.nextTokensPerBatch = safeNextToken;
741	        info.preTokensPerBatch =
742	            static_cast<int32_t>(info.actS2Size) - static_cast<int32_t>(info.actS1Size) + safePreToken;
743	    } else {
744	        info.nextTokensPerBatch = static_cast<int32_t>(info.actS2Size) - static_cast<int32_t>(info.actS1Size);
745	        info.preTokensPerBatch = 0;
746	        if (constInfo.sinkNumber > 0) {
747	            if (constInfo.sparseMode == fa_base_vector::RIGHT_DOWN_CAUSAL &&
748	                static_cast<int32_t>(info.actS2Size) - static_cast<int32_t>(constInfo.sinkNumber) <
749	                    static_cast<int32_t>(info.actS1Size)) {
750	                info.nextTokensPerBatch = static_cast<int32_t>(info.actS2Size) -
751	                                          static_cast<int32_t>(constInfo.sinkNumber) -
752	                                          static_cast<int32_t>(info.actS1Size);
753	            } else if (constInfo.sparseMode == fa_base_vector::LEFT_UP_CAUSAL) {
754	                info.nextTokensPerBatch = safeNextToken;
755	            }
756	        }
757	    }
758	
759	    // 情况1: loop不等于0时, 第一个S2 inner循环就是第一个S2 outer循环, 即s2Cur=0
760	    // 情况2: loop=0时, 如果(bN2Start, gS1Start, s2Start)任务有效, 对于当前核, 为第一个S2 inner循环
761	    // 情况3: loop=0时, 如果(bN2Start, gS1Start, s2Start)任务无效, 下一个有效任务一定是某个head的第一个S2外切块，s2Cur=0
762	    info.isFirstSInnerLoop = ((loop == 0) || (s2Cur == curS2Start));
763	    if (info.isFirstSInnerLoop) {
764	        bn2IdxInCurCore++;
765	    }
766	    info.bn2IdxInCurCore = bn2IdxInCurCore - 1;
767	
768	    info.tndIsS2SplitCore = false;
769	    info.tndCoreStartKVSplitPos = 0;
770	    info.isLastS2Loop = (s2Cur + 1 == curS2End);
771	    info.curSInnerLoopTimes = curS2End - curS2Start;
772	    if (constInfo.keySinkNumber) {
773	        info.curSInnerLoopTimes += 1; // 多一轮 sink 任务
774	    }
775	
776	    if (constInfo.bN2Start == constInfo.bN2End && constInfo.gS1Start == constInfo.gS1End) {
777	        // 所有任务属于同一个S1G
778	        info.tndIsS2SplitCore = true;
779	        info.tndCoreStartKVSplitPos = constInfo.coreStartKVSplitPos;
780	    } else {
781	        if (constInfo.headS2Split && (bN2Cur == constInfo.bN2Start) && (gS1Cur == constInfo.gS1Start)) {
782	            // 当前任务属于第一个S1G, 并且第一个S1G的S2被切分了
783	            info.tndIsS2SplitCore = true;
784	            info.tndCoreStartKVSplitPos = constInfo.coreStartKVSplitPos;
785	        } else if (constInfo.tailS2Split && (bN2Cur == constInfo.bN2End) && (gS1Cur == constInfo.gS1End)) {
786	            // 当前任务属于最后一个S1G, 并且最后一个S1G的S2被切分了
787	            info.tndIsS2SplitCore = true;
788	        }
789	    }
790	
791	    if (constInfo.sinkNumber > 0 && constInfo.sparseMode == fa_base_vector::BAND) {
792	        if constexpr (FLASH_DECODE) {
793	            if (info.tndIsS2SplitCore) { // sinkNumber性能优化场景，sparseMode4中间块跳过不算，但需要将LSE拷贝出去
794	                uint32_t sinkBlockLastIndex =
795	                    (static_cast<uint32_t>(constInfo.sinkNumber) + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize - 1;
796	                if (s2Cur == sinkBlockLastIndex && sinkBlockLastIndex + 1 < firstTokenWithSinkNumber &&
797	                    curS2End <= firstTokenWithSinkNumber) {
798	                    info.isLastS2Loop |= true;
799	                }
800	            }
801	        }
802	    }
803	
804	    if constexpr (FLASH_DECODE) {
805	        if (info.tndIsS2SplitCore) {
806	            CalcAccumOffset(info);
807	        }
808	    }
809	}
