957	template <typename FIAT>
958	__aicore__ inline void FiaKernelNonQuant<FIAT>::UpdateAxisInfo(uint32_t &bN2Cur, uint32_t &gS1Cur, uint32_t &s2Cur)
959	{
960	    uint64_t s2LoopTimes = (actSeqLensKv + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize;
961	    uint64_t gS1Size = actSeqLensQ * constInfo.gSize;
962	    uint64_t gS1LoopTimes = (gS1Size + constInfo.mBaseSize - 1) / constInfo.mBaseSize;
963	
964	    // 当前S2未处理完
965	    if (s2Cur + 1 < s2LoopTimes) {
966	        s2Cur++;
967	        return;
968	    }
969	
970	    // 当前BN2未处理完
971	    s2Cur = 0;
972	    if (gS1Cur + 1 < gS1LoopTimes) {
973	        gS1Cur++;
974	        return;
975	    }
976	
977	    // 当前BN2已处理完
978	    gS1Cur = 0;
979	    bN2Cur++;
980	}
