982	template <typename FIAT>
983	__aicore__ inline void FiaKernelNonQuant<FIAT>::CreateTask(uint64_t loop,
984	                                                           uint32_t bN2Cur,
985	                                                           uint32_t gS1Cur,
986	                                                           uint32_t s2Cur,
987	                                                           bool isS1GFirstBlock,
988	                                                           RunInfo extraInfo[FIA_PRELOAD_TASK_CACHE_SIZE])
989	{
990	    RunInfo &extraInfo0 = extraInfo[loop % FIA_PRELOAD_TASK_CACHE_SIZE]; // 本轮任务
991	    RunInfo &extraInfo2 = extraInfo[(loop + 2) % FIA_PRELOAD_TASK_CACHE_SIZE]; // 上一轮任务
992	    RunInfo &extraInfo1 = extraInfo[(loop + 1) % FIA_PRELOAD_TASK_CACHE_SIZE]; // 上两轮任务
993	    if (constInfo.keySinkNumber && isS1GFirstBlock) {
994	        extraInfo0.isSinkTensor = true;
995	    }
996	
997	    CalcParams(loop, bN2Cur, gS1Cur, s2Cur, extraInfo0);
998	    if (constInfo.keySinkNumber && isS1GFirstBlock) {
999	        sinkTaskPending = true;
1000	        extraInfo0.isLastS2Loop = false; // 新增：sink 永远不是最后一轮
1001	    } else if (sinkTaskPending) {
1002	        extraInfo0.isChangeBatch = false;
1003	        extraInfo0.isFirstSInnerLoop = false;
1004	        bn2IdxInCurCore--;
1005	        extraInfo0.bn2IdxInCurCore = bn2IdxInCurCore - 1;
1006	        sinkTaskPending = false;
1007	    }
1008	
1009	    extraInfo0.isValid = true;
1010	}
