1023	template <typename FIAT>
1024	__aicore__ inline void FiaKernelNonQuant<FIAT>::ExecuteTask(uint64_t loop,
1025	                                                            RunInfo extraInfo[FIA_PRELOAD_TASK_CACHE_SIZE])
1026	{
1027	    RunInfo &extraInfo0 = extraInfo[loop % FIA_PRELOAD_TASK_CACHE_SIZE]; // 本轮任务
1028	    RunInfo &extraInfo2 = extraInfo[(loop + 2) % FIA_PRELOAD_TASK_CACHE_SIZE]; // 上一轮任务
1029	    RunInfo &extraInfo1 = extraInfo[(loop + 1) % FIA_PRELOAD_TASK_CACHE_SIZE]; // 上两轮任务
1030	
1031	    if (extraInfo0.isValid) {
1032	        if ASCEND_IS_AIC {
1033	            ComputeMm1(extraInfo0);
1034	        }
1035	    }
1036	    if (extraInfo2.isValid) {
1037	        if ASCEND_IS_AIV {
1038	            ComputeVec1(extraInfo2);
1039	        }
1040	        if ASCEND_IS_AIC {
1041	            ComputeMm2(extraInfo2);
1042	        }
1043	    }
1044	    if (extraInfo1.isValid) {
1045	        if ASCEND_IS_AIV {
1046	            ComputeVec2(extraInfo1);
1047	        }
1048	        extraInfo1.isValid = false;
1049	        extraInfo1.isSinkTensor = false;
1050	    }
1051	}
