1053	template <typename FIAT>
1054	__aicore__ inline TASK_DEAL_MODE
1055	FiaKernelNonQuant<FIAT>::GetTaskDealMode(uint32_t bN2Cur, uint32_t gS1Cur, uint32_t s2Cur, bool &isS1GFirstBlock)
1056	{
1057	    bool isFirstTask = (bN2Cur == constInfo.bN2Start) && (gS1Cur == constInfo.gS1Start) && (s2Cur == constInfo.s2Start);
1058	    uint32_t bIdx = GetBIdx(bN2Cur);
1059	    if (isFirstTask || prevBIdx != bIdx) {
1060	        prevBIdx = bIdx;
1061	        if (constInfo.actualLenDims == 0 && !constInfo.batchContinuous) {
1062	            actSeqLensKv = fa_base_kernel::SeqLenFromTensorList<LAYOUT_T>(keyPtr, bIdx);
1063	        } else {
1064	            actSeqLensKv = kvActSeqLensParser.GetActualSeqLength(bIdx);
1065	        }
1066	        actSeqLensQ = qActSeqLensParser.GetActualSeqLength(bIdx);
1067	    }
1068	    uint64_t s2LoopTimes = (actSeqLensKv + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize;
1069	
1070	    uint64_t gS1Size = actSeqLensQ * constInfo.gSize;
1071	    uint64_t gS1LoopTimes = (gS1Size + constInfo.mBaseSize - 1) / constInfo.mBaseSize;
1072	
1073	    if (s2LoopTimes == 0 || gS1LoopTimes == 0) {
1074	        if (gS1Cur == 0 && s2Cur == 0) {
1075	            return TASK_DEAL_MODE::DEAL_ZERO;
1076	        }
1077	        return TASK_DEAL_MODE::SKIP;
1078	    }
1079	
1080	    // 计算每一行的起止点，只有当换行时（bN2Cur、gS1Cur更新）才需要重新计算
1081	    if (isFirstTask || bN2Cur != prevBN2Idx || gS1Cur != prevGS1Idx) {
1082	        if (constInfo.attenMaskFlag == 0U) {
1083	            CalcCurS2StartEndNoSparse(bN2Cur, gS1Cur);
1084	        } else {
1085	            CalcCurS2StartEndWithSparse(bN2Cur, gS1Cur);
1086	        }
1087	        if ((bN2Cur != prevBN2Idx) || (gS1Cur != prevGS1Idx)) {
1088	            isS1GFirstBlock = true;
1089	        }
1090	        prevBN2Idx = bN2Cur;
1091	        prevGS1Idx = gS1Cur;
1092	    }
1093	    if (s2Cur >= curS2End) {
1094	        return TASK_DEAL_MODE::SKIP;
1095	    }
1096	
1097	    if (likely(constInfo.sinkNumber > 0 && constInfo.sparseMode == fa_base_vector::BAND)) {
1098	        uint32_t sinkBlockLastIndex =
1099	            (static_cast<uint32_t>(constInfo.sinkNumber) + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize - 1;
1100	        if (s2Cur > sinkBlockLastIndex && s2Cur < firstTokenWithSinkNumber) {
1101	            return TASK_DEAL_MODE::SKIP;
1102	        }
1103	    } else if (s2Cur < curS2Start) {
1104	        return TASK_DEAL_MODE::SKIP;
1105	    }
1106	    return TASK_DEAL_MODE::CREATE_TASK;
1107	}
