1109	template <typename FIAT>
1110	__aicore__ inline void FiaKernelNonQuant<FIAT>::GetPreNextTokenLeftUp(int64_t actSeqLensQ,
1111	                                                                      int64_t actSeqLensKv,
1112	                                                                      int64_t &preTokenLeftUp,
1113	                                                                      int64_t &nextTokenLeftUp)
1114	{
1115	    preTokenLeftUp = constInfo.preToken;
1116	    nextTokenLeftUp = constInfo.nextToken;
1117	    GetSafeActToken(actSeqLensQ, actSeqLensKv, preTokenLeftUp, nextTokenLeftUp);
1118	
1119	    if (constInfo.sparseMode == fa_base_vector::BAND) {
1120	        preTokenLeftUp = static_cast<int64_t>(actSeqLensQ) - static_cast<int64_t>(actSeqLensKv) + preTokenLeftUp;
1121	    }
1122	
1123	    if (constInfo.sparseMode == fa_base_vector::RIGHT_DOWN_CAUSAL) {
1124	        nextTokenLeftUp = static_cast<int64_t>(actSeqLensKv) - static_cast<int64_t>(actSeqLensQ);
1125	    } else if (constInfo.sparseMode == fa_base_vector::BAND) {
1126	        nextTokenLeftUp = static_cast<int64_t>(actSeqLensKv) - static_cast<int64_t>(actSeqLensQ) + nextTokenLeftUp;
1127	    }
1128	}
