1130	template <typename FIAT>
1131	__aicore__ inline void FiaKernelNonQuant<FIAT>::CalcCurS2StartEndNoSparse(uint32_t bN2Cur, uint32_t gS1Cur)
1132	{
1133	    curS2Start = 0U;
1134	    curS2End = (static_cast<uint32_t>(actSeqLensKv) + constInfo.s2BaseSize - 1) / constInfo.s2BaseSize;
1135	
1136	    if ((bN2Cur == constInfo.bN2Start) && (gS1Cur == constInfo.gS1Start)) {
1137	        constInfo.headS2Split = constInfo.s2Start != 0U;
1138	        curS2Start = constInfo.s2Start;
1139	    }
1140	
1141	    if ((bN2Cur == constInfo.bN2End) && (gS1Cur == constInfo.gS1End)) {
1142	        constInfo.tailS2Split = constInfo.s2End != 0U;
1143	        curS2End = constInfo.s2End;
1144	    }
1145	}
