1147	template <typename FIAT>
1148	__aicore__ inline void FiaKernelNonQuant<FIAT>::CalcCurS2StartEndWithSparse(uint32_t bN2Cur, uint32_t gS1Cur)
1149	{
1150	    // 1. Calc preTokenLeftUp, nextTokenLeftUp
1151	    int64_t preTokenLeftUp = 0;
1152	    int64_t nextTokenLeftUp = 0;
1153	    GetPreNextTokenLeftUp(actSeqLensQ, actSeqLensKv, preTokenLeftUp, nextTokenLeftUp);
1154	
1155	    // 2. calc index of s2FirstToken, s2LastToken by index of s1GFirstToken, s1GLastToken
1156	    int64_t s1GFirstToken = static_cast<int64_t>(gS1Cur) * static_cast<int64_t>(constInfo.mBaseSize);
1157	    int64_t s1GLastToken = Min(s1GFirstToken + static_cast<int64_t>(constInfo.mBaseSize),
1158	                               static_cast<int64_t>(actSeqLensQ) * static_cast<int64_t>(constInfo.gSize)) -
1159	                           1;
1160	
1161	    int64_t s1FirstToken = 0;
1162	    int64_t s1LastToken = 0;
1163	    if constexpr (GetOutUbFormat<LAYOUT_T>() == UbFormat::S1G) {
1164	        s1FirstToken = static_cast<int64_t>(s1GFirstToken / constInfo.gSize);
1165	        s1LastToken = static_cast<int64_t>(s1GLastToken / constInfo.gSize);
1166	    } else {
1167	        if (s1GFirstToken / static_cast<int64_t>(actSeqLensQ) == s1GLastToken / static_cast<int64_t>(actSeqLensQ)) {
1168	            // start and end locate in one G
1169	            s1FirstToken = s1GFirstToken % static_cast<int64_t>(actSeqLensQ);
1170	            s1LastToken = s1GLastToken % static_cast<int64_t>(actSeqLensQ);
1171	        } else {
1172	            // start and end locate in tow or more G, but working same as crossing one complete block
1173	            s1FirstToken = 0;
1174	            s1LastToken = static_cast<int64_t>(actSeqLensQ);
1175	        }
1176	    }
1177	
1178	    // 3. trans index of token to index of block
1179	    uint32_t s2StartWithSparse = 0U;
1180	    uint32_t s2EndWithSparse = 0U;
1181	    int64_t s2FirstToken = s1FirstToken - preTokenLeftUp;
1182	    int64_t s2LastToken = s1LastToken + nextTokenLeftUp;
1183	    // no valid token
1184	    if (s2FirstToken >= static_cast<int64_t>(actSeqLensKv) || s2LastToken < 0 || s2LastToken < s2FirstToken) {
1185	        curS2Start = 0U;
1186	        curS2End = 0U;
1187	        return;
1188	    }
1189	    // get valid range
1190	    s2FirstToken = ClipSInnerToken(s2FirstToken, 0, static_cast<int64_t>(actSeqLensKv - 1));
1191	    s2LastToken = ClipSInnerToken(s2LastToken, 0, static_cast<int64_t>(actSeqLensKv - 1));
1192	
1193	    s2StartWithSparse = static_cast<uint32_t>(s2FirstToken) / constInfo.s2BaseSize;
1194	    s2EndWithSparse = static_cast<uint32_t>(s2LastToken) / constInfo.s2BaseSize + 1U;
1195	
1196	    // 增加sink_num场景sparseMode=4时，从零开始
1197	    firstTokenWithSinkNumber = s2StartWithSparse;
1198	    if (constInfo.sinkNumber > 0 && constInfo.sparseMode == fa_base_vector::BAND) {
1199	        s2StartWithSparse = 0;
1200	    }
1201	
1202	    // 4. Calc curS2Start, curS2End
1203	    curS2Start = s2StartWithSparse;
1204	    curS2End = s2EndWithSparse;
1205	
1206	    if (bN2Cur == constInfo.bN2Start && gS1Cur == constInfo.gS1Start) { // first line
1207	        constInfo.headS2Split = constInfo.s2Start > s2StartWithSparse ? true : false;
1208	        curS2Start = Max(s2StartWithSparse, constInfo.s2Start);
1209	        firstTokenWithSinkNumber = Max(firstTokenWithSinkNumber, constInfo.s2Start);
1210	    }
1211	    if (bN2Cur == constInfo.bN2End && gS1Cur == constInfo.gS1End) { // last line
1212	        constInfo.tailS2Split = constInfo.s2End > 0U ? true : false;
1213	        curS2End = constInfo.s2End > 0U ? Min(s2EndWithSparse, constInfo.s2End) : s2EndWithSparse;
1214	    }
1215	    return;
1216	}
1217	
1218	template <typename FIAT> __aicore__ inline void FiaKernelNonQuant<FIAT>::FlashAttention()
1219	{
1220	    RunInfo extraInfo[FIA_PRELOAD_TASK_CACHE_SIZE];
1221	
1222	    uint32_t bN2Cur = constInfo.bN2Start;
1223	    uint32_t gS1Cur = constInfo.gS1Start;
1224	    uint32_t s2Cur = constInfo.s2Start;
1225	    prevBN2Idx = bN2Cur;
1226	    prevGS1Idx = gS1Cur;
1227	
1228	    uint64_t createdTaskCount = 0;
1229	    uint64_t executedTaskCount = 0;
1230	
1231	    bool shouldDispatchTask = true;
1232	    bool shouldExecuteTask = false;
1233	    bool isS1GFirstBlock = true; // 在constInfo.keySinkNumber场景下，每个S1G处理的第一个block块是sink块，需特殊适配
1234	
1235	    if ASCEND_IS_AIV {
1236	        CrossCoreSetFlag<ConstInfo::FIA_SYNC_MODE2, PIPE_MTE3>(constInfo.syncV2C2);
1237	    }
1238	
1239	    while (shouldDispatchTask || shouldExecuteTask) {
1240	        // 分发任务
1241	        shouldDispatchTask = ShouldDispatchTask(bN2Cur, gS1Cur, s2Cur);
1242	        if (shouldDispatchTask) {
1243	            TASK_DEAL_MODE taskDealMode = GetTaskDealMode(bN2Cur, gS1Cur, s2Cur, isS1GFirstBlock);
1244	            if (taskDealMode == TASK_DEAL_MODE::CREATE_TASK) {
1245	                // 创建任务
1246	                if (constInfo.keySinkNumber && isS1GFirstBlock) {
1247	                    CreateTask(createdTaskCount, bN2Cur, gS1Cur, s2Cur, isS1GFirstBlock, extraInfo);
1248	                    createdTaskCount++;
1249	                    isS1GFirstBlock = false;
1250	                } else {
1251	                    CreateTask(createdTaskCount, bN2Cur, gS1Cur, s2Cur, false, extraInfo);
1252	                    createdTaskCount++;
1253	                    UpdateAxisInfo(bN2Cur, gS1Cur, s2Cur);
1254	                }
1255	            } else if (taskDealMode == TASK_DEAL_MODE::DEAL_ZERO) {
1256	                DealZeroActSeqLen(bN2Cur, gS1Cur, s2Cur);
1257	                UpdateAxisInfo(bN2Cur, gS1Cur, s2Cur);
1258	                continue;
1259	            } else if (taskDealMode == TASK_DEAL_MODE::SKIP) {
1260	                UpdateAxisInfo(bN2Cur, gS1Cur, s2Cur);
1261	                continue;
1262	            }
1263	        }
1264	        // 执行任务
1265	        shouldExecuteTask = ShouldExecuteTask(extraInfo);
1266	        if (shouldExecuteTask) {
1267	            ExecuteTask(executedTaskCount, extraInfo);
1268	            executedTaskCount++;
1269	        }
1270	    }
1271	
1272	    if ASCEND_IS_AIC {
1273	        CrossCoreWaitFlag(constInfo.syncV2C2);
1274	    }
1275	}
1276	template <typename FIAT> __aicore__ inline void FiaKernelNonQuant<FIAT>::Process()
1277	{
1278	    // usedCoreNum: 使用的总核数
1279	    if (aiCoreIdx < usedCoreNum) {
1280	        if ASCEND_IS_AIV {
1281	            vectorService.InitBuffers(pipe);
1282	            vectorService.AllocEventID();
1283	        } else {
1284	            matmulService.InitBuffers(pipe);
1285	            matmulService.AllocEventID();
1286	        }
1287	        FlashAttention();
1288	        if ASCEND_IS_AIV {
1289	            vectorService.FreeEventID();
1290	        } else {
1291	            matmulService.FreeEventID();
1292	        }
1293	    }
1294	    if constexpr (FLASH_DECODE) {
1295	        if (unlikely(fdFlag)) {
1296	            FlashDecode();
1297	        }
1298	    }
1299	}
1300	
1301	#endif // FIA_KERNEL_NONQUANT_SINK_H

